package org.dejaq.plugins.musictracker.navigation;

import java.util.List;
import java.util.Optional;
import net.runelite.api.coords.WorldPoint;
import org.dejaq.plugins.musictracker.track.InteractionTarget;
import org.dejaq.plugins.musictracker.track.TrackStep;

public abstract class AbstractStageProgressionEngine implements StageProgressionEngine
{
	protected static final int MAXIMUM_INTERACTION_SNAP_DISTANCE = 3;
	protected static final double INTERACTION_PROXIMITY_SCORE_MULTIPLIER = 0.25;
	protected static final double FORWARD_STAGE_BIAS_WEIGHT = 0.4;

	@Override
	public int findClosestStageIndex(List<TrackStep> trackSteps, WorldPoint currentPlayerLocation)
	{
		if (trackSteps == null || trackSteps.isEmpty() || currentPlayerLocation == null)
		{
			return 0;
		}

		int closestStageIndex = 0;
		double bestScore = Double.MAX_VALUE;

		for (int stageIndex = 0; stageIndex < trackSteps.size(); stageIndex++)
		{
			TrackStep trackStep = trackSteps.get(stageIndex);
			if (trackStep == null || trackStep.getDestination() == null)
			{
				continue;
			}

			double distanceToDestination = currentPlayerLocation.distanceTo(trackStep.getDestination());

			if (trackStep.hasAdvancementInteraction())
			{
				for (InteractionTarget advancementInteraction : trackStep.getAdvancementInteractions())
				{
					WorldPoint interactionLocation = advancementInteraction.getEffectiveLocation(trackStep.getDestination());
					if (interactionLocation == null)
					{
						continue;
					}
					double distanceToInteraction = currentPlayerLocation.distanceTo(interactionLocation);
					if (distanceToInteraction <= MAXIMUM_INTERACTION_SNAP_DISTANCE)
					{
						distanceToDestination = Math.min(distanceToDestination, distanceToInteraction * INTERACTION_PROXIMITY_SCORE_MULTIPLIER);
					}
				}
			}

			double score = distanceToDestination + (stageIndex * FORWARD_STAGE_BIAS_WEIGHT);
			if (score < bestScore)
			{
				bestScore = score;
				closestStageIndex = stageIndex;
			}
		}
		return closestStageIndex;
	}

	@Override
	public Optional<Integer> findMatchingUpcomingStage(List<TrackStep> trackSteps, int currentStageIndex,
													   WorldPoint currentPlayerLocation, boolean planeChanged, boolean regionChanged)
	{
		if (trackSteps == null || (!planeChanged && !regionChanged))
		{
			return Optional.empty();
		}

		for (int stageIndex = currentStageIndex + 1; stageIndex < trackSteps.size(); stageIndex++)
		{
			TrackStep trackStep = trackSteps.get(stageIndex);
			if (trackStep == null || trackStep.getDestination() == null)
			{
				continue;
			}

			boolean matchesNewPlane = planeChanged && trackStep.getDestination().getPlane() == currentPlayerLocation.getPlane();
			boolean matchesNewRegion = regionChanged && trackStep.getDestination().getRegionID() == currentPlayerLocation.getRegionID();

			if (matchesNewPlane || matchesNewRegion)
			{
				return Optional.of(stageIndex);
			}
		}
		return Optional.empty();
	}

	protected boolean isSamePlane(WorldPoint firstPoint, WorldPoint secondPoint)
	{
		return firstPoint != null && secondPoint != null && firstPoint.getPlane() == secondPoint.getPlane();
	}

	protected WorldPoint resolveAdvancementPoint(TrackStep trackStep, InteractionTarget advancementInteraction)
	{
		return advancementInteraction.getEffectiveLocation(trackStep.getDestination());
	}
}

package org.dejaq.plugins.musictracker.navigation;

import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Optional;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import org.dejaq.plugins.musictracker.MusicTrack;
import org.dejaq.plugins.musictracker.MusicTrackManager;
import org.dejaq.plugins.musictracker.track.UnlockType;
import org.dejaq.plugins.musictracker.state.TrackingStateService;
import org.dejaq.plugins.musictracker.track.TrackStep;

@Singleton
public class AutoProgressionService
{

	private static final double SIGNIFICANT_STEP_PROXIMITY_ADVANTAGE_IN_TILES = 5.0;

	@Inject
	private Client client;
	@Inject
	private MusicTrackManager musicTrackManager;
	@Inject
	private TrackingStateService trackingStateService;

	private StageProgressionEngine stageProgressionEngine = new DefaultStageProgressionEngine();

	public Optional<MusicTrack> findNextAutoProgressableTrackInRegion(String regionName)
	{
		if (regionName == null)
		{
			return Optional.empty();
		}

		List<MusicTrack> eligibleTracksInRegion = musicTrackManager.getTracksForRegion(regionName).stream()
			.filter(candidateTrack -> !trackingStateService.isTrackSkipped(candidateTrack.getTitle()))
			.filter(candidateTrack -> !trackingStateService.isTrackUnlocked(candidateTrack.getTitle()))
			.filter(this::isAutoProgressable)
			.collect(Collectors.toList());

		if (eligibleTracksInRegion.isEmpty())
		{
			return Optional.empty();
		}

		WorldPoint currentPlayerLocation = client.getLocalPlayer() != null ? client.getLocalPlayer().getWorldLocation() : null;
		if (currentPlayerLocation == null)
		{
			return Optional.of(eligibleTracksInRegion.get(0));
		}

		Optional<MusicTrack> closestByFinalDestination = findClosestByFinalDestination(eligibleTracksInRegion, currentPlayerLocation);
		Optional<MusicTrack> closestByIntermediateStep = findClosestByIntermediateStep(eligibleTracksInRegion, currentPlayerLocation);

		if (closestByFinalDestination.isEmpty())
		{
			return closestByIntermediateStep;
		}
		if (closestByIntermediateStep.isEmpty())
		{
			return closestByFinalDestination;
		}

		double finalDestinationDistance = musicTrackManager.distanceTo(currentPlayerLocation, closestByFinalDestination.get().getUnlockPoint());
		double intermediateStepDistance = distanceToClosestStep(closestByIntermediateStep.get(), currentPlayerLocation);

		boolean intermediateStepIsSignificantlyCloser =
			(finalDestinationDistance - intermediateStepDistance) >= SIGNIFICANT_STEP_PROXIMITY_ADVANTAGE_IN_TILES;

		return intermediateStepIsSignificantlyCloser ? closestByIntermediateStep : closestByFinalDestination;
	}

	private Optional<MusicTrack> findClosestByFinalDestination(List<MusicTrack> eligibleTracksInRegion, WorldPoint currentPlayerLocation)
	{
		return eligibleTracksInRegion.stream()
			.min(Comparator.comparingDouble(candidateTrack -> musicTrackManager.distanceTo(currentPlayerLocation, candidateTrack.getUnlockPoint())));
	}

	private Optional<MusicTrack> findClosestByIntermediateStep(List<MusicTrack> eligibleTracksInRegion, WorldPoint currentPlayerLocation)
	{
		return eligibleTracksInRegion.stream()
			.min(Comparator.comparingDouble(candidateTrack -> distanceToClosestStep(candidateTrack, currentPlayerLocation)));
	}

	private double distanceToClosestStep(MusicTrack musicTrack, WorldPoint currentPlayerLocation)
	{
		List<TrackStep> defaultSteps = musicTrack.getDefaultSteps();
		if (defaultSteps.isEmpty())
		{
			return musicTrackManager.distanceTo(currentPlayerLocation, musicTrack.getUnlockPoint());
		}

		int closestStageIndex = stageProgressionEngine.findClosestStageIndex(defaultSteps, currentPlayerLocation);
		TrackStep closestTrackStep = defaultSteps.get(closestStageIndex);
		return musicTrackManager.distanceTo(currentPlayerLocation, closestTrackStep.getDestination());
	}

	public Optional<String> findNextPendingRegion(String currentRegionName)
	{
		List<String> regionNamesInOrder = musicTrackManager.getRegionNames();
		int currentRegionIndex = regionNamesInOrder.indexOf(currentRegionName);
		return Optional.ofNullable(musicTrackManager.getNextPendingRegion(
			regionNamesInOrder, trackingStateService.getSkippedTrackTitles(), currentRegionIndex + 1));
	}

	public Optional<MusicTrack> findNextClosestTrackToCurrent(MusicTrack currentMusicTrack)
	{
		if (currentMusicTrack == null)
		{
			return Optional.empty();
		}
		return Optional.ofNullable(musicTrackManager.getNextClosestToCurrentTrack(
			currentMusicTrack, trackingStateService.getSkippedTrackTitles(), trackingStateService.getCurrentUnlockedTrackTitles()));
	}

	private boolean isAutoProgressable(MusicTrack musicTrack)
	{
		return musicTrack.getUnlockType() == null
			|| musicTrack.getUnlockType() == UnlockType.NORMAL;
	}

	public String buildCompletionMessage()
	{
		Set<String> remainingTrackCategories = new HashSet<>();

		for (MusicTrack musicTrack : musicTrackManager.getAllTracks())
		{
			if (trackingStateService.isTrackUnlocked(musicTrack.getTitle()) || trackingStateService.isTrackSkipped(musicTrack.getTitle()))
			{
				continue;
			}
			if (musicTrack.getUnlockType() == UnlockType.HOLIDAY_EVENT)
			{
				remainingTrackCategories.add("holiday");
			}
			else if (musicTrack.getUnlockType() == UnlockType.QUEST)
			{
				remainingTrackCategories.add("quest");
			}
			else
			{
				remainingTrackCategories.add("normal");
			}
		}

		boolean hasSkippedTracks = !trackingStateService.getSkippedTrackTitles().isEmpty();

		if (remainingTrackCategories.isEmpty())
		{
			return hasSkippedTracks
				? "Congratulations! You've unlocked all music tracks (excluding skipped ones). You can clear skipped tracks in the settings."
				: "Congratulations! You've unlocked every music track in the game.";
		}

		StringBuilder completionMessageBuilder = new StringBuilder("Congratulations! You've unlocked all ");

		if (remainingTrackCategories.contains("normal")
			|| (remainingTrackCategories.contains("quest") && remainingTrackCategories.contains("holiday")))
		{
			completionMessageBuilder.append("non-quest and non-holiday ");
		}
		else if (remainingTrackCategories.contains("quest"))
		{
			completionMessageBuilder.append("non-quest ");
		}
		else if (remainingTrackCategories.contains("holiday"))
		{
			completionMessageBuilder.append("non-holiday ");
		}

		completionMessageBuilder.append("music tracks.");

		if (hasSkippedTracks)
		{
			completionMessageBuilder.append(" You still have skipped tracks. You can clear them in the settings.");
		}

		return completionMessageBuilder.toString();
	}
}

package org.dejaq.plugins.musictracker.navigation;

import javax.inject.Singleton;
import net.runelite.api.coords.WorldPoint;
import org.dejaq.plugins.musictracker.track.InteractionTarget;
import org.dejaq.plugins.musictracker.track.TrackStep;

@Singleton
public class DefaultStageProgressionEngine extends AbstractStageProgressionEngine
{
	@Override
	public boolean hasCompletedStep(ProgressionContext progressionContext)
	{
		TrackStep currentTrackStep = progressionContext.getCurrentStep();
		WorldPoint currentPlayerLocation = progressionContext.getCurrentPlayerLocation();

		if (currentTrackStep == null || currentTrackStep.getDestination() == null || currentPlayerLocation == null)
		{
			return false;
		}

		if (!currentTrackStep.hasAdvancementInteraction()
			&& currentPlayerLocation.distanceTo(currentTrackStep.getDestination()) <= 1)
		{
			return true;
		}

		for (InteractionTarget advancementInteraction : currentTrackStep.getAdvancementInteractions())
		{
			WorldPoint interactionLocation = resolveAdvancementPoint(currentTrackStep, advancementInteraction);
			if (interactionLocation != null && currentPlayerLocation.distanceTo(interactionLocation) == 0)
			{
				return true;
			}
		}
		return false;
	}

	@Override
	public boolean hasCrossedInteractionPoint(TrackStep currentTrackStep, WorldPoint previousPlayerLocation, WorldPoint currentPlayerLocation)
	{
		if (currentTrackStep == null || !currentTrackStep.hasAdvancementInteraction() || previousPlayerLocation == null)
		{
			return false;
		}

		for (InteractionTarget advancementInteraction : currentTrackStep.getAdvancementInteractions())
		{
			WorldPoint interactionPoint = resolveAdvancementPoint(currentTrackStep, advancementInteraction);
			if (hasPassedThroughPoint(previousPlayerLocation, currentPlayerLocation, interactionPoint))
			{
				return true;
			}
		}
		return false;
	}

	private boolean hasPassedThroughPoint(WorldPoint previousLocation, WorldPoint currentLocation, WorldPoint targetPoint)
	{
		if (targetPoint == null || previousLocation == null || currentLocation == null)
		{
			return false;
		}
		if (previousLocation.getPlane() != targetPoint.getPlane() || currentLocation.getPlane() != targetPoint.getPlane())
		{
			return false;
		}

		boolean crossedOnXAxis = (previousLocation.getX() < targetPoint.getX() && currentLocation.getX() >= targetPoint.getX())
			|| (previousLocation.getX() > targetPoint.getX() && currentLocation.getX() <= targetPoint.getX());

		boolean crossedOnYAxis = (previousLocation.getY() < targetPoint.getY() && currentLocation.getY() >= targetPoint.getY())
			|| (previousLocation.getY() > targetPoint.getY() && currentLocation.getY() <= targetPoint.getY());

		if (!crossedOnXAxis && !crossedOnYAxis)
		{
			return false;
		}

		return currentLocation.distanceTo(targetPoint) <= 1;
	}
}

package org.dejaq.plugins.musictracker.navigation;

import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;
import net.runelite.client.util.ImageUtil;
import org.dejaq.plugins.musictracker.MusicTrack;
import org.dejaq.plugins.musictracker.MusicTrackerConfig;
import org.dejaq.plugins.musictracker.MusicTrackerPlugin;

@Slf4j
@Singleton
public class NavigationCoordinator
{
	private static final String SHORTEST_PATH_PLUGIN_NAMESPACE = "shortestpath";
	private static final String SHORTEST_PATH_MESSAGE_NAME = "path";
	private static final String SHORTEST_PATH_CLEAR_MESSAGE_NAME = "clear";
	private static final String SHORTEST_PATH_TARGET_DATA_KEY = "target";
	private static final String WORLD_MAP_POINT_ICON_RESOURCE_NAME = "icon_cape.png";

	private static final BufferedImage WORLD_MAP_POINT_ICON = ImageUtil.loadImageResource(
		MusicTrackerPlugin.class, WORLD_MAP_POINT_ICON_RESOURCE_NAME);

	@Inject
	private ClientThread clientThread;
	@Inject
	private EventBus eventBus;
	@Inject
	private WorldMapPointManager worldMapPointManager;
	@Inject
	private MusicTrackerConfig musicTrackerConfig;

	private final List<WorldMapPoint> activeWorldMapPoints = new ArrayList<>();
	private WorldPoint lastRequestedTargetWorldPoint;

	public void onNavigationTargetChanged(MusicTrack currentMusicTrack, WorldPoint currentTargetWorldPoint)
	{
		if (currentTargetWorldPoint != null)
		{
			requestShortestPathTo(currentTargetWorldPoint);
		}
		if (currentMusicTrack != null)
		{
			updateWorldMapPointForTrack(currentMusicTrack, currentTargetWorldPoint);
		}
	}

	public void requestShortestPathTo(WorldPoint targetWorldPoint)
	{
		if (targetWorldPoint == null || (targetWorldPoint.getX() == 0 && targetWorldPoint.getY() == 0))
		{
			return;
		}
		if (!musicTrackerConfig.useShortestPath())
		{
			return;
		}
		if (targetWorldPoint.equals(lastRequestedTargetWorldPoint))
		{
			return;
		}
		lastRequestedTargetWorldPoint = targetWorldPoint;

		clientThread.invokeLater(() -> {
			Map<String, Object> shortestPathRequestData = new HashMap<>();
			shortestPathRequestData.put(SHORTEST_PATH_TARGET_DATA_KEY, targetWorldPoint);
			eventBus.post(new PluginMessage(SHORTEST_PATH_PLUGIN_NAMESPACE, SHORTEST_PATH_MESSAGE_NAME, shortestPathRequestData));
		});
	}

	public void updateWorldMapPointForTrack(MusicTrack musicTrack, WorldPoint preferredTargetWorldPoint)
	{
		if (!musicTrackerConfig.showWorldMapPoints())
		{
			return;
		}

		clearWorldMapPoints();

		WorldPoint worldMapPointLocation = preferredTargetWorldPoint != null ? preferredTargetWorldPoint : musicTrack.getUnlockPoint();
		if (worldMapPointLocation == null || (worldMapPointLocation.getX() == 0 && worldMapPointLocation.getY() == 0))
		{
			log.debug("No unlock point found for track {}", musicTrack.getTitle());
			return;
		}

		WorldMapPoint worldMapPoint = new WorldMapPoint(worldMapPointLocation, WORLD_MAP_POINT_ICON);
		worldMapPoint.setName(musicTrack.getTitle());
		worldMapPoint.setTooltip(musicTrack.getTitle());
		worldMapPoint.setJumpOnClick(true);
		worldMapPoint.setSnapToEdge(true);

		worldMapPointManager.add(worldMapPoint);
		activeWorldMapPoints.add(worldMapPoint);

		log.debug("Added world map point at {} for track {}", worldMapPointLocation, musicTrack.getTitle());
	}

	// todo we don't really want this here - will fix when back from vacation
	public void clearShortestPath()
	{
		clientThread.invokeLater(() -> {
			eventBus.post(new PluginMessage(
				SHORTEST_PATH_PLUGIN_NAMESPACE,
				SHORTEST_PATH_CLEAR_MESSAGE_NAME,
				Collections.emptyMap()
			));
		});
	}

	public void clearWorldMapPoints()
	{
		for (WorldMapPoint worldMapPoint : activeWorldMapPoints)
		{
			worldMapPointManager.remove(worldMapPoint);
		}
		activeWorldMapPoints.clear();
	}

	public void forgetLastRequestedTarget()
	{
		lastRequestedTargetWorldPoint = null;
	}
}

package org.dejaq.plugins.musictracker.navigation;

import java.util.List;
import lombok.Getter;
import net.runelite.api.coords.WorldPoint;
import org.dejaq.plugins.musictracker.track.TrackStep;

@Getter
public class ProgressionContext
{
	private final List<TrackStep> trackSteps;
	private final int currentStageIndex;
	private final WorldPoint previousPlayerLocation;
	private final WorldPoint currentPlayerLocation;

	public ProgressionContext(List<TrackStep> trackSteps, int currentStageIndex, WorldPoint previousPlayerLocation, WorldPoint currentPlayerLocation)
	{
		this.trackSteps = trackSteps;
		this.currentStageIndex = currentStageIndex;
		this.previousPlayerLocation = previousPlayerLocation;
		this.currentPlayerLocation = currentPlayerLocation;
	}

	public TrackStep getCurrentStep()
	{
		if (trackSteps == null || currentStageIndex < 0 || currentStageIndex >= trackSteps.size())
		{
			return null;
		}
		return trackSteps.get(currentStageIndex);
	}

	public TrackStep getNextStep()
	{
		int nextStageIndex = currentStageIndex + 1;
		if (trackSteps == null || nextStageIndex < 0 || nextStageIndex >= trackSteps.size())
		{
			return null;
		}
		return trackSteps.get(nextStageIndex);
	}

	public TrackStep getPreviousStep()
	{
		int previousStageIndex = currentStageIndex - 1;
		if (trackSteps == null || previousStageIndex < 0 || previousStageIndex >= trackSteps.size())
		{
			return null;
		}
		return trackSteps.get(previousStageIndex);
	}
}

