package org.dejaq.plugins.musictracker.navigation;

import javax.inject.Inject;
import javax.inject.Singleton;
import org.dejaq.plugins.musictracker.MusicTrackerConfig;

@Singleton
public class StageProgressionEngineSelector
{
	private final MusicTrackerConfig musicTrackerConfig;
	private final DefaultStageProgressionEngine defaultStageProgressionEngine;
	private final ProximityStageProgressionEngine proximityStageProgressionEngine;
	private final RelativeDistanceStageProgressionEngine relativeDistanceStageProgressionEngine;
	private final SegmentProjectionStageProgressionEngine segmentProjectionStageProgressionEngine;

	@Inject
	public StageProgressionEngineSelector(
		MusicTrackerConfig musicTrackerConfig,
		DefaultStageProgressionEngine defaultStageProgressionEngine,
		ProximityStageProgressionEngine proximityStageProgressionEngine,
		RelativeDistanceStageProgressionEngine relativeDistanceStageProgressionEngine,
		SegmentProjectionStageProgressionEngine segmentProjectionStageProgressionEngine)
	{
		this.musicTrackerConfig = musicTrackerConfig;
		this.defaultStageProgressionEngine = defaultStageProgressionEngine;
		this.proximityStageProgressionEngine = proximityStageProgressionEngine;
		this.relativeDistanceStageProgressionEngine = relativeDistanceStageProgressionEngine;
		this.segmentProjectionStageProgressionEngine = segmentProjectionStageProgressionEngine;
	}

	public StageProgressionEngine getActiveEngine()
	{
		ProgressionSystem progressionSystem = musicTrackerConfig.progressionSystem();
		if (progressionSystem == null)
		{
			return defaultStageProgressionEngine;
		}

		switch (progressionSystem)
		{
			case PROXIMITY:
				return proximityStageProgressionEngine;
			case RELATIVE_DISTANCE:
				return relativeDistanceStageProgressionEngine;
			case SEGMENT_PROJECTION:
				return segmentProjectionStageProgressionEngine;
			case DEFAULT:
			default:
				return defaultStageProgressionEngine;
		}
	}
}

package org.dejaq.plugins.musictracker.navigation;

import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.callback.ClientThread;
import org.dejaq.plugins.musictracker.MusicTrack;
import org.dejaq.plugins.musictracker.MusicTrackerPlugin;
import org.dejaq.plugins.musictracker.track.InteractionTarget;
import org.dejaq.plugins.musictracker.track.MusicTrackEntityPoint;
import org.dejaq.plugins.musictracker.track.Route;
import org.dejaq.plugins.musictracker.track.SpecialTrackRegistry;
import org.dejaq.plugins.musictracker.track.TrackStep;
import org.dejaq.plugins.musictracker.track.UnlockType;
import org.dejaq.plugins.musictracker.track.special.SpecialTrackHandler;

@Singleton
public class TrackNavigator
{
	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;

	private final MusicTrackerPlugin musicTrackerPlugin;
	private final StageProgressionEngineSelector stageProgressionEngineSelector;
	@Getter
	private final NavigationCoordinator navigationCoordinator;

	@Getter
	private MusicTrack currentTrack;
	@Getter
	private Route currentRoute;
	@Getter
	private int currentStage = 0;
	@Getter
	private final List<MusicTrackEntityPoint> activeEntityHighlights = new ArrayList<>();

	private WorldPoint lastPlayerLocation;

	@Inject
	public TrackNavigator(MusicTrackerPlugin musicTrackerPlugin, StageProgressionEngineSelector stageProgressionEngineSelector, NavigationCoordinator navigationCoordinator)
	{
		this.musicTrackerPlugin = musicTrackerPlugin;
		this.stageProgressionEngineSelector = stageProgressionEngineSelector;
		this.navigationCoordinator = navigationCoordinator;
	}

	public void setCurrentTrack(MusicTrack musicTrack)
	{
		if (!client.isClientThread())
		{
			clientThread.invokeLater(() -> setCurrentTrack(musicTrack));
			return;
		}
		this.currentTrack = musicTrack;
		this.currentRoute = musicTrack != null ? musicTrack.getDefaultRoute() : null;
		this.currentStage = 0;
		this.lastPlayerLocation = null;

		SpecialTrackRegistry.resetAll();

		applySpecialTrackStepContributions();

		populateAllFutureHighlights();

		navigationCoordinator.clearShortestPath();

		if (musicTrack != null && musicTrack.getUnlockType() == UnlockType.NORMAL) // we keep setting the route for non-pathed tracks
		{
			navigationCoordinator.onNavigationTargetChanged(currentTrack, getCurrentTargetPoint());
		}
	}

	public void setCurrentRoute(Route route)
	{
		if (!client.isClientThread())
		{
			clientThread.invokeLater(() -> setCurrentRoute(route));
			return;
		}
		if (currentTrack == null || route == null)
		{
			return;
		}
		this.currentRoute = route;
		this.currentStage = 0;
		this.lastPlayerLocation = null;

		SpecialTrackRegistry.resetAll();

		applySpecialTrackStepContributions();

		populateAllFutureHighlights();
		navigationCoordinator.onNavigationTargetChanged(currentTrack, getCurrentTargetPoint());
	}

	public boolean setCurrentRouteByIndex(int routeIndex)
	{
		if (currentTrack == null)
		{
			return false;
		}
		List<Route> allRoutesForTrack = currentTrack.getAllRoutes();
		if (routeIndex < 0 || routeIndex >= allRoutesForTrack.size())
		{
			return false;
		}
		setCurrentRoute(allRoutesForTrack.get(routeIndex));
		return true;
	}

	public void clear()
	{
		this.currentTrack = null;
		this.currentRoute = null;
		this.currentStage = 0;
		this.lastPlayerLocation = null;
		navigationCoordinator.clearShortestPath();
		navigationCoordinator.clearWorldMapPoints();
		clearEntityHighlights();
		SpecialTrackRegistry.resetAll();
	}

	private void applySpecialTrackStepContributions()
	{
		if (currentTrack == null || currentRoute == null)
		{
			return;
		}

		SpecialTrackHandler specialTrackHandler = SpecialTrackRegistry.getHandler(currentTrack, currentRoute);

		List<TrackStep> existingTrackSteps = currentRoute.getTrackSteps() != null
			? currentRoute.getTrackSteps()
			: List.of();

		List<TrackStep> contributedTrackSteps = specialTrackHandler.contributeTrackSteps(currentTrack, currentRoute, existingTrackSteps);

		if (contributedTrackSteps != null && contributedTrackSteps != existingTrackSteps)
		{
			currentRoute.setTrackSteps(contributedTrackSteps);
		}
	}

	public boolean hasActiveTrackStep()
	{
		return currentTrack != null && hasSteps();
	}

	public TrackStep getCurrentStep()
	{
		return hasActiveTrackStep() ? getTrackStep(currentStage) : null;
	}

	public List<TrackStep> getCurrentSteps()
	{
		if (currentRoute != null && currentRoute.hasSteps())
		{
			return currentRoute.getTrackSteps();
		}
		return currentTrack != null ? currentTrack.getDefaultSteps() : List.of();
	}

	public int getTrackStepCount()
	{
		return getCurrentSteps().size();
	}

	public TrackStep getTrackStep(int stageIndex)
	{
		List<TrackStep> currentSteps = getCurrentSteps();
		if (stageIndex < 0 || stageIndex >= currentSteps.size())
		{
			return null;
		}
		return currentSteps.get(stageIndex);
	}

	public boolean hasSteps()
	{
		return !getCurrentSteps().isEmpty();
	}

	public WorldPoint getCurrentTargetPoint()
	{
		TrackStep currentTrackStep = getCurrentStep();
		if (currentTrackStep != null && currentTrackStep.getDestination() != null)
		{
			return currentTrackStep.getDestination();
		}
		return currentTrack != null ? currentTrack.getFinalDestination() : null;
	}

	public void setCurrentStage(int newStageIndex)
	{
		if (!client.isClientThread())
		{
			clientThread.invokeLater(() -> setCurrentStage(newStageIndex));
			return;
		}
		if (!hasActiveTrackStep())
		{
			return;
		}
		int highestValidStageIndex = getTrackStepCount() - 1;
		this.currentStage = Math.max(0, Math.min(newStageIndex, highestValidStageIndex));
		populateAllFutureHighlights();
		navigationCoordinator.onNavigationTargetChanged(currentTrack, getCurrentTargetPoint());
	}

	public void jumpToLastStage()
	{
		if (hasActiveTrackStep())
		{
			setCurrentStage(getTrackStepCount() - 1);
		}
	}

	public void clearEntityHighlights()
	{
		activeEntityHighlights.clear();
	}

	public void populateAllFutureHighlights()
	{
		if (!client.isClientThread())
		{
			clientThread.invokeLater(this::populateAllFutureHighlights);
			return;
		}
		activeEntityHighlights.clear();
		if (!hasActiveTrackStep())
		{
			return;
		}

		SpecialTrackHandler specialTrackHandler = SpecialTrackRegistry.getHandler(currentTrack, currentRoute);

		for (int stageIndex = currentStage; stageIndex < getTrackStepCount(); stageIndex++)
		{
			TrackStep trackStep = getTrackStep(stageIndex);
			if (trackStep == null)
			{
				continue;
			}
			if (stageIndex == currentStage)
			{
				List<MusicTrackEntityPoint> dynamicHighlights = specialTrackHandler.getDynamicEntityHighlights(
					currentTrack, currentRoute, trackStep, stageIndex, musicTrackerPlugin);

				if (dynamicHighlights != null)
				{
					activeEntityHighlights.addAll(dynamicHighlights);
					continue;
				}
			}

			for (InteractionTarget interactionTarget : trackStep.getAllHighlights())
			{
				MusicTrackEntityPoint entityHighlight = createHighlightForInteraction(trackStep, interactionTarget);
				if (entityHighlight != null)
				{
					activeEntityHighlights.add(entityHighlight);
				}
			}
		}
	}

	private MusicTrackEntityPoint createHighlightForInteraction(TrackStep trackStep, InteractionTarget interactionTarget)
	{
		if (interactionTarget == null)
		{
			return null;
		}
		WorldPoint highlightLocation = interactionTarget.getLocation() != null
			? interactionTarget.getLocation()
			: trackStep.getDestination();
		if (highlightLocation == null)
		{
			return null;
		}

		MusicTrackEntityPoint entityHighlight = MusicTrackEntityPoint.from(highlightLocation, interactionTarget);
		entityHighlight.setInteractionTarget(interactionTarget);
		return entityHighlight;
	}

	public void checkProgress()
	{
		if (!hasActiveTrackStep())
		{
			return;
		}

		clientThread.invokeLater(() -> {
			Player localPlayer = client.getLocalPlayer();
			if (localPlayer == null)
			{
				return;
			}

			WorldPoint currentPlayerLocation = localPlayer.getWorldLocation();
			SpecialTrackHandler specialTrackHandler = SpecialTrackRegistry.getHandler(currentTrack, currentRoute);

			if (specialTrackHandler.hasVolatileDynamicHighlights(currentTrack, currentRoute, musicTrackerPlugin))
			{
				populateAllFutureHighlights();
			}

			Integer forcedStageIndex = specialTrackHandler.getForcedStageIndex(currentTrack, currentRoute, currentStage, currentPlayerLocation, musicTrackerPlugin);
			if (forcedStageIndex != null && forcedStageIndex != currentStage)
			{
				setCurrentStage(forcedStageIndex);
				lastPlayerLocation = currentPlayerLocation;
				return;
			}

			if (!specialTrackHandler.canProgress(currentTrack, currentRoute, musicTrackerPlugin))
			{
				return;
			}

			StageProgressionEngine stageProgressionEngine = stageProgressionEngineSelector.getActiveEngine();

			ProgressionContext progressionContext = new ProgressionContext(
				getCurrentSteps(), currentStage, lastPlayerLocation, currentPlayerLocation);

			if (stageProgressionEngine.hasCompletedStep(progressionContext))
			{
				advanceStage();
				lastPlayerLocation = currentPlayerLocation;
				return;
			}

			boolean isFirstTickSinceStart = (lastPlayerLocation == null);
			boolean hasChangedPlane = lastPlayerLocation != null && lastPlayerLocation.getPlane() != currentPlayerLocation.getPlane();
			boolean hasChangedRegion = lastPlayerLocation != null && lastPlayerLocation.getRegionID() != currentPlayerLocation.getRegionID();

			if (isFirstTickSinceStart)
			{
				resyncToClosestStage(currentPlayerLocation);
			}
			else if (hasChangedPlane || hasChangedRegion)
			{
				resyncAfterPlaneOrRegionChange(currentPlayerLocation, hasChangedPlane, hasChangedRegion);
			}
			else
			{
				resetIfMovedSignificantlyBackward(currentPlayerLocation);
			}

			if (stageProgressionEngine.hasCrossedInteractionPoint(getCurrentStep(), lastPlayerLocation, currentPlayerLocation))
			{
				advanceStage();
			}

			lastPlayerLocation = currentPlayerLocation;
		});
	}

	private void advanceStage()
	{
		currentStage++;
		navigationCoordinator.onNavigationTargetChanged(currentTrack, getCurrentTargetPoint());
	}

	private void resyncToClosestStage(WorldPoint currentPlayerLocation)
	{
		int closestStageIndex = stageProgressionEngineSelector.getActiveEngine().findClosestStageIndex(getCurrentSteps(), currentPlayerLocation);
		if (closestStageIndex != currentStage)
		{
			currentStage = closestStageIndex;
			navigationCoordinator.onNavigationTargetChanged(currentTrack, getCurrentTargetPoint());
		}
	}

	private void resyncAfterPlaneOrRegionChange(WorldPoint currentPlayerLocation, boolean hasChangedPlane, boolean hasChangedRegion)
	{
		StageProgressionEngine stageProgressionEngine = stageProgressionEngineSelector.getActiveEngine();

		Optional<Integer> matchingUpcomingStage = stageProgressionEngine.findMatchingUpcomingStage(
			getCurrentSteps(), currentStage, currentPlayerLocation, hasChangedPlane, hasChangedRegion);

		if (matchingUpcomingStage.isPresent())
		{
			currentStage = matchingUpcomingStage.get();
			navigationCoordinator.onNavigationTargetChanged(currentTrack, getCurrentTargetPoint());
			return;
		}

		int closestStageIndex = stageProgressionEngine.findClosestStageIndex(getCurrentSteps(), currentPlayerLocation);
		if (closestStageIndex == currentStage)
		{
			return;
		}

		TrackStep closestTrackStep = getTrackStep(closestStageIndex);
		boolean closestStepMatchesCurrentPlane = closestTrackStep != null && closestTrackStep.getDestination() != null
			&& closestTrackStep.getDestination().getPlane() == currentPlayerLocation.getPlane();

		boolean isAllowedBackwardMove = (closestStageIndex < currentStage) && closestStepMatchesCurrentPlane;
		boolean isSignificantBackwardMove = closestStageIndex < currentStage - 1;
		boolean isForwardMove = closestStageIndex > currentStage;

		if (isForwardMove || isSignificantBackwardMove || isAllowedBackwardMove)
		{
			currentStage = closestStageIndex;
			navigationCoordinator.onNavigationTargetChanged(currentTrack, getCurrentTargetPoint());
		}
	}

	private void resetIfMovedSignificantlyBackward(WorldPoint currentPlayerLocation)
	{
		if (currentStage == 0)
		{
			return;
		}
		int closestStageIndex = stageProgressionEngineSelector.getActiveEngine().findClosestStageIndex(getCurrentSteps(), currentPlayerLocation);
		if (closestStageIndex < currentStage - 1)
		{
			currentStage = closestStageIndex;
			navigationCoordinator.onNavigationTargetChanged(currentTrack, getCurrentTargetPoint());
		}
	}
}

package org.dejaq.plugins.musictracker.overlay;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.DecorativeObject;
import net.runelite.api.GameObject;
import net.runelite.api.GroundObject;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.TileObject;
import net.runelite.api.WallObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import org.dejaq.plugins.musictracker.MusicTrackerConfig;
import org.dejaq.plugins.musictracker.MusicTrackerPlugin;
import org.dejaq.plugins.musictracker.entity.SceneEntityFinder;
import org.dejaq.plugins.musictracker.track.InteractionTarget;
import org.dejaq.plugins.musictracker.track.InteractionType;
import org.dejaq.plugins.musictracker.track.MusicTrackEntityPoint;

public class EntityHighlightOverlay extends Overlay
{
	private static final int HIGHLIGHT_OUTLINE_STROKE_WIDTH = 2;
	private static final int HINT_TEXT_VERTICAL_OFFSET = 8;

	private final Client client;
	private final MusicTrackerPlugin musicTrackerPlugin;
	private final MusicTrackerConfig musicTrackerConfig;
	private final SceneEntityFinder sceneEntityFinder;

	private final Map<MusicTrackEntityPoint, NPC> resolvedNpcsByEntityPoint = new IdentityHashMap<>();
	private final Map<MusicTrackEntityPoint, TileObject> resolvedGameObjectsByEntityPoint = new IdentityHashMap<>();
	private List<MusicTrackEntityPoint> lastSeenHighlightList;
	private int lastResolvedAtTick = -1;

	@Inject
	public EntityHighlightOverlay(Client client, MusicTrackerPlugin musicTrackerPlugin, MusicTrackerConfig musicTrackerConfig, SceneEntityFinder sceneEntityFinder)
	{
		this.client = client;
		this.musicTrackerPlugin = musicTrackerPlugin;
		this.musicTrackerConfig = musicTrackerConfig;
		this.sceneEntityFinder = sceneEntityFinder;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		List<MusicTrackEntityPoint> activeEntityHighlights = musicTrackerPlugin.getTrackNavigator().getActiveEntityHighlights();
		if (activeEntityHighlights == null || activeEntityHighlights.isEmpty())
		{
			lastSeenHighlightList = null;
			resolvedNpcsByEntityPoint.clear();
			resolvedGameObjectsByEntityPoint.clear();
			return null;
		}

		refreshResolvedEntitiesIfNeeded(activeEntityHighlights);

		for (MusicTrackEntityPoint entityHighlightPoint : activeEntityHighlights)
		{
			if (entityHighlightPoint == null)
			{
				continue;
			}
			renderEntityHighlight(graphics, entityHighlightPoint);
		}

		return null;
	}

	private void refreshResolvedEntitiesIfNeeded(List<MusicTrackEntityPoint> activeEntityHighlights)
	{
		int currentTick = client.getTickCount();
		if (activeEntityHighlights == lastSeenHighlightList && currentTick == lastResolvedAtTick)
		{
			return;
		}

		resolvedNpcsByEntityPoint.clear();
		resolvedGameObjectsByEntityPoint.clear();

		for (MusicTrackEntityPoint entityHighlightPoint : activeEntityHighlights)
		{
			if (entityHighlightPoint == null || entityHighlightPoint.getInteractionType() == InteractionType.TILE)
			{
				continue;
			}

			if (entityHighlightPoint.getInteractionType() == InteractionType.NPC)
			{
				sceneEntityFinder.findNpc(entityHighlightPoint)
					.ifPresent(resolvedNpc -> resolvedNpcsByEntityPoint.put(entityHighlightPoint, resolvedNpc));
			}
			else
			{
				sceneEntityFinder.findGameObject(entityHighlightPoint)
					.ifPresent(resolvedGameObject -> resolvedGameObjectsByEntityPoint.put(entityHighlightPoint, resolvedGameObject));
			}
		}

		lastSeenHighlightList = activeEntityHighlights;
		lastResolvedAtTick = currentTick;
	}

	private void renderEntityHighlight(Graphics2D graphics, MusicTrackEntityPoint entityHighlightPoint)
	{
		Shape highlightShape = resolveHighlightShape(entityHighlightPoint);
		if (highlightShape == null)
		{
			return;
		}

		Color highlightFillColor = musicTrackerConfig.entityHighlightFillColor();
		Color highlightOutlineColor = musicTrackerConfig.entityHighlightOutlineColor();

		graphics.setColor(highlightFillColor);
		graphics.fill(highlightShape);

		graphics.setColor(highlightOutlineColor);
		graphics.setStroke(new BasicStroke(HIGHLIGHT_OUTLINE_STROKE_WIDTH));
		graphics.draw(highlightShape);

		InteractionTarget interactionTarget = entityHighlightPoint.getInteractionTarget();
		if (interactionTarget != null && interactionTarget.getHint() != null && !interactionTarget.getHint().isBlank())
		{
			Point hintTextPosition = getTextPositionAboveShape(highlightShape, graphics, interactionTarget.getHint());
			OverlayUtil.renderTextLocation(graphics, hintTextPosition, interactionTarget.getHint(), highlightOutlineColor);
		}
	}

	private Shape resolveHighlightShape(MusicTrackEntityPoint entityHighlightPoint)
	{
		if (entityHighlightPoint.getInteractionType() == InteractionType.TILE)
		{
			return resolveTileHighlightShape(entityHighlightPoint);
		}
		if (entityHighlightPoint.getInteractionType() == InteractionType.NPC)
		{
			NPC resolvedNpc = resolvedNpcsByEntityPoint.get(entityHighlightPoint);
			return resolvedNpc != null ? resolvedNpc.getConvexHull() : null;
		}
		TileObject resolvedGameObject = resolvedGameObjectsByEntityPoint.get(entityHighlightPoint);
		return resolvedGameObject != null ? getObjectConvexHull(resolvedGameObject) : null;
	}

	private Shape resolveTileHighlightShape(MusicTrackEntityPoint entityHighlightPoint)
	{
		WorldPoint tileWorldLocation = new WorldPoint(entityHighlightPoint.getWorldX(), entityHighlightPoint.getWorldY(), entityHighlightPoint.getPlane());
		LocalPoint tileLocalPoint = LocalPoint.fromWorld(client, tileWorldLocation);
		if (tileLocalPoint == null)
		{
			return null;
		}
		return Perspective.getCanvasTilePoly(client, tileLocalPoint);
	}

	private Shape getObjectConvexHull(TileObject tileObject)
	{
		if (tileObject == null) {
			return null;
		}
		if (tileObject instanceof GameObject)
		{
			return ((GameObject) tileObject).getConvexHull();
		}
		if (tileObject instanceof WallObject)
		{
			return ((WallObject) tileObject).getConvexHull();
		}
		if (tileObject instanceof DecorativeObject)
		{
			return ((DecorativeObject) tileObject).getConvexHull();
		}
		if (tileObject instanceof GroundObject)
		{
			return ((GroundObject) tileObject).getConvexHull();
		}
		return null;
	}

	private Point getTextPositionAboveShape(Shape highlightShape, Graphics2D graphics, String hintText)
	{
		Rectangle shapeBounds = highlightShape.getBounds();
		FontMetrics fontMetrics = graphics.getFontMetrics();

		int hintTextWidth = fontMetrics.stringWidth(hintText);
		int hintTextX = shapeBounds.x + (shapeBounds.width / 2) - (hintTextWidth / 2);
		int hintTextY = shapeBounds.y - HINT_TEXT_VERTICAL_OFFSET;

		return new Point(hintTextX, hintTextY);
	}
}

package org.dejaq.plugins.musictracker.overlay;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import org.dejaq.plugins.musictracker.MusicTrackerConfig;
import org.dejaq.plugins.musictracker.MusicTrackerPlugin;

public class MusicTrackMinimapOverlay extends Overlay
{

	private static final int ARROW_BREATHING_PERIOD_TICKS = 1;
	private static final int ARROW_LENGTH_PIXELS = 23;
	private static final int ARROW_HALF_WIDTH_PIXELS = 9;
	private static final int ARROW_BACK_NOTCH_DEPTH_PIXELS = 22;
	private static final int ARROW_TIP_BLUNT_INSET_PIXELS = 1;
	private static final int ARROW_TIP_BLUNT_HALF_WIDTH_PIXELS = 0;
	private static final int ARROW_EDGE_INSET_PIXELS = 4;
	private static final int DESTINATION_DOT_DIAMETER_PIXELS = 8;

	private final Client client;
	private final MusicTrackerPlugin musicTrackerPlugin;
	private final MusicTrackerConfig musicTrackerConfig;
	private final EventBus eventBus;

	private int gameTickCounter;

	@Inject
	public MusicTrackMinimapOverlay(Client client, MusicTrackerPlugin musicTrackerPlugin, MusicTrackerConfig musicTrackerConfig, EventBus eventBus)
	{
		this.client = client;
		this.musicTrackerPlugin = musicTrackerPlugin;
		this.musicTrackerConfig = musicTrackerConfig;
		this.eventBus = eventBus;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	public void startUp()
	{
		gameTickCounter = 0;
		eventBus.register(this);
	}

	public void shutDown()
	{
		eventBus.unregister(this);
		gameTickCounter = 0;
	}

	@Subscribe
	public void onGameTick(GameTick gameTick)
	{
		gameTickCounter++;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!musicTrackerPlugin.isTrackingActive() || !musicTrackerConfig.showMinimapArrow() || !isArrowVisibleThisTick())
		{
			return null;
		}

		WorldPoint targetWorldPoint = musicTrackerPlugin.getTrackNavigator().getCurrentTargetPoint();
		if (targetWorldPoint == null || (targetWorldPoint.getX() == 0 && targetWorldPoint.getY() == 0))
		{
			return null;
		}

		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null || targetWorldPoint.getPlane() != client.getLocalPlayer().getWorldView().getPlane())
		{
			return null;
		}

		WorldPoint playerWorldPoint = localPlayer.getWorldLocation();
		int totalDistanceTiles = playerWorldPoint.distanceTo(targetWorldPoint);
		if (totalDistanceTiles <= 0 || totalDistanceTiles == Integer.MAX_VALUE)
		{
			return null;
		}

		MinimapProbeResult probeResult = findFarthestVisiblePointTowardTarget(playerWorldPoint, targetWorldPoint, totalDistanceTiles);
		if (probeResult == null)
		{
			return null;
		}

		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		if (probeResult.reachedActualDestination)
		{
			drawDestinationDot(graphics, probeResult.minimapPoint);
			return null;
		}

		drawEdgeArrow(graphics, playerWorldPoint, probeResult.minimapPoint);
		return null;
	}

	private boolean isArrowVisibleThisTick()
	{
		if (musicTrackerConfig.minimapArrowStatic())
		{
			return true;
		}
		return (gameTickCounter / ARROW_BREATHING_PERIOD_TICKS) % 2 == 0;
	}

	private void drawDestinationDot(Graphics2D graphics, Point minimapPoint)
	{
		int outlineDiameter = DESTINATION_DOT_DIAMETER_PIXELS + 2;
		graphics.setColor(Color.BLACK);
		graphics.fillOval(minimapPoint.getX() - outlineDiameter / 2, minimapPoint.getY() - outlineDiameter / 2, outlineDiameter, outlineDiameter);

		graphics.setColor(musicTrackerConfig.minimapArrowColor());
		graphics.fillOval(minimapPoint.getX() - DESTINATION_DOT_DIAMETER_PIXELS / 2, minimapPoint.getY() - DESTINATION_DOT_DIAMETER_PIXELS / 2,
			DESTINATION_DOT_DIAMETER_PIXELS, DESTINATION_DOT_DIAMETER_PIXELS);
	}

	private void drawEdgeArrow(Graphics2D graphics, WorldPoint playerWorldPoint, Point edgeMinimapPoint)
	{
		LocalPoint playerLocalPoint = LocalPoint.fromWorld(client, playerWorldPoint);

		Point playerMinimapPoint = playerLocalPoint != null ? Perspective.localToMinimap(client, playerLocalPoint) : null;
		if (playerMinimapPoint == null)
		{
			return;
		}

		double directionX = edgeMinimapPoint.getX() - playerMinimapPoint.getX();
		double directionY = edgeMinimapPoint.getY() - playerMinimapPoint.getY();
		double directionMagnitude = Math.hypot(directionX, directionY);
		if (directionMagnitude < 1.0)
		{
			return;
		}

		double unitDirectionX = directionX / directionMagnitude;
		double unitDirectionY = directionY / directionMagnitude;
		int insetTipX = (int) Math.round(edgeMinimapPoint.getX() - unitDirectionX * ARROW_EDGE_INSET_PIXELS);
		int insetTipY = (int) Math.round(edgeMinimapPoint.getY() - unitDirectionY * ARROW_EDGE_INSET_PIXELS);

		double arrowAngleRadians = Math.atan2(directionY, directionX);
		drawArrowhead(graphics, insetTipX, insetTipY, arrowAngleRadians);
	}

	private MinimapProbeResult findFarthestVisiblePointTowardTarget(WorldPoint playerWorldPoint, WorldPoint targetWorldPoint, int totalDistanceTiles)
	{
		int lowTileDistance = 0;
		int highTileDistance = totalDistanceTiles;
		Point farthestVisiblePoint = null;
		int farthestVisibleTileDistance = 0;

		while (lowTileDistance <= highTileDistance)
		{
			int midTileDistance = (lowTileDistance + highTileDistance) / 2;
			WorldPoint probeWorldPoint = interpolateWorldPoint(playerWorldPoint, targetWorldPoint, midTileDistance, totalDistanceTiles);
			LocalPoint probeLocalPoint = LocalPoint.fromWorld(client, probeWorldPoint);
			Point probeMinimapPoint = probeLocalPoint != null ? Perspective.localToMinimap(client, probeLocalPoint) : null;

			if (probeMinimapPoint != null)
			{
				farthestVisiblePoint = probeMinimapPoint;
				farthestVisibleTileDistance = midTileDistance;
				lowTileDistance = midTileDistance + 1;
			}
			else
			{
				highTileDistance = midTileDistance - 1;
			}
		}

		if (farthestVisiblePoint == null)
		{
			return null;
		}

		return new MinimapProbeResult(farthestVisiblePoint, farthestVisibleTileDistance == totalDistanceTiles);
	}

	private WorldPoint interpolateWorldPoint(WorldPoint fromPoint, WorldPoint toPoint, int stepDistance, int totalDistance)
	{
		double interpolationRatio = (double) stepDistance / totalDistance;
		int interpolatedX = fromPoint.getX() + (int) Math.round((toPoint.getX() - fromPoint.getX()) * interpolationRatio);
		int interpolatedY = fromPoint.getY() + (int) Math.round((toPoint.getY() - fromPoint.getY()) * interpolationRatio);
		return new WorldPoint(interpolatedX, interpolatedY, fromPoint.getPlane());
	}

	private void drawArrowhead(Graphics2D graphics, int tipX, int tipY, double angleRadians)
	{
		Polygon arrowPolygon = new Polygon();
		arrowPolygon.addPoint(-ARROW_TIP_BLUNT_INSET_PIXELS, -ARROW_TIP_BLUNT_HALF_WIDTH_PIXELS);
		arrowPolygon.addPoint(-ARROW_LENGTH_PIXELS, -ARROW_HALF_WIDTH_PIXELS);
		arrowPolygon.addPoint(-ARROW_BACK_NOTCH_DEPTH_PIXELS, 0);
		arrowPolygon.addPoint(-ARROW_LENGTH_PIXELS, ARROW_HALF_WIDTH_PIXELS);
		arrowPolygon.addPoint(-ARROW_TIP_BLUNT_INSET_PIXELS, ARROW_TIP_BLUNT_HALF_WIDTH_PIXELS);

		Graphics2D arrowGraphics = (Graphics2D) graphics.create();
		arrowGraphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		arrowGraphics.translate(tipX, tipY);
		arrowGraphics.rotate(angleRadians);

		arrowGraphics.setColor(musicTrackerConfig.minimapArrowColor());
		arrowGraphics.fillPolygon(arrowPolygon);

		arrowGraphics.setColor(Color.BLACK);
		arrowGraphics.setStroke(new BasicStroke(2f));
		arrowGraphics.drawPolygon(arrowPolygon);

		arrowGraphics.dispose();
	}

	private static final class MinimapProbeResult
	{
		private final Point minimapPoint;
		private final boolean reachedActualDestination;

		private MinimapProbeResult(Point minimapPoint, boolean reachedActualDestination)
		{
			this.minimapPoint = minimapPoint;
			this.reachedActualDestination = reachedActualDestination;
		}
	}
}

package org.dejaq.plugins.musictracker.overlay;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
