@Slf4j
public class MusicTrackOverlay extends Overlay
{
	private static final int MINIMUM_PANEL_WIDTH = 200;
	private static final int WIDTH_SAFETY_MARGIN_PIXELS = 20;

	private final Client client;
	private final MusicTrackerPlugin musicTrackerPlugin;
	private final MusicTrackerConfig musicTrackerConfig;
	private final RequirementSectionRenderer requirementSectionRenderer = new RequirementSectionRenderer();

	private final PanelComponent panelComponent = new PanelComponent();

	private MusicTrack cachedNextSuggestedTrack;
	private MusicTrack cachedNextSuggestedTrackForCurrentTrack;
	private int cachedNextSuggestedTrackAtTick = -1;

	@Inject
	public MusicTrackOverlay(Client client, MusicTrackerPlugin musicTrackerPlugin, MusicTrackerConfig musicTrackerConfig)
	{
		this.client = client;
		this.musicTrackerPlugin = musicTrackerPlugin;
		this.musicTrackerConfig = musicTrackerConfig;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setResizable(true);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!musicTrackerPlugin.isTrackingActive())
		{
			return null;
		}

		panelComponent.getChildren().clear();
		panelComponent.getChildren().add(TitleComponent.builder().text("Music Tracker").color(Color.WHITE).build());

		MusicTrack currentMusicTrack = musicTrackerPlugin.getTrackNavigator().getCurrentTrack();

		int requiredPanelWidth = MINIMUM_PANEL_WIDTH;

		if (currentMusicTrack == null || currentMusicTrack.getTitle() == null)
		{
			panelComponent.getChildren().add(TitleComponent.builder().text("Please select a Music Track").color(Color.LIGHT_GRAY).build());
		}
		else
		{
			requiredPanelWidth = Math.max(requiredPanelWidth, computeRequiredPanelWidth(graphics, currentMusicTrack));
			renderCurrentTrackDetails(currentMusicTrack);
		}

		panelComponent.setPreferredSize(new Dimension(requiredPanelWidth, 0));
		return panelComponent.render(graphics);
	}

	private int computeRequiredPanelWidth(Graphics2D graphics, MusicTrack currentMusicTrack)
	{
		FontMetrics fontMetrics = graphics.getFontMetrics();
		int requiredWidth = MINIMUM_PANEL_WIDTH;

		Route currentRoute = resolveCurrentRoute(currentMusicTrack);
		String trackingValueText = currentMusicTrack.getTitle()
			+ (currentRoute != null && currentMusicTrack.hasMultipleRoutes() ? " [" + currentRoute.getName() + "]" : "");
		int trackingLineWidth = fontMetrics.stringWidth("Tracking:") + fontMetrics.stringWidth(trackingValueText);
		requiredWidth = Math.max(requiredWidth, trackingLineWidth + WIDTH_SAFETY_MARGIN_PIXELS);

		if (musicTrackerConfig.showNextTrackOverlay())
		{
			try
			{
				MusicTrack nextSuggestedTrack = getCachedNextSuggestedTrack(currentMusicTrack);
				if (nextSuggestedTrack != null && nextSuggestedTrack.getTitle() != null && !nextSuggestedTrack.getTitle().equals(currentMusicTrack.getTitle()))
				{
					int nextLineWidth = fontMetrics.stringWidth("Next:") + fontMetrics.stringWidth(nextSuggestedTrack.getTitle());
					requiredWidth = Math.max(requiredWidth, nextLineWidth + WIDTH_SAFETY_MARGIN_PIXELS);
				}
			}
			catch (Exception exception)
			{
				log.debug("Error getting next track while sizing overlay", exception);
			}
		}

		return requiredWidth;
	}

	private Route resolveCurrentRoute(MusicTrack currentMusicTrack)
	{
		Route currentRoute = musicTrackerPlugin.getTrackNavigator().getCurrentRoute();
		if (currentRoute == null)
		{
			currentRoute = currentMusicTrack.getDefaultRoute();
		}
		return currentRoute;
	}

	private void renderCurrentTrackDetails(MusicTrack currentMusicTrack)
	{
		Route currentRoute = resolveCurrentRoute(currentMusicTrack);
		if (currentRoute == null)
		{
			renderNoRouteTrackDetails(currentMusicTrack);
			return;
		}

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Tracking:")
			.right(currentMusicTrack.getTitle() + (currentMusicTrack.hasMultipleRoutes() ? " [" + currentRoute.getName() + "]" : ""))
			.leftColor(Color.WHITE)
			.rightColor(ColorScheme.PROGRESS_INPROGRESS_COLOR)
			.build());

		if (musicTrackerConfig.showRegionOverlay())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Region:")
				.right(currentMusicTrack.getRegion() != null ? currentMusicTrack.getRegion() : "Unknown")
				.leftColor(Color.WHITE)
				.rightColor(Color.LIGHT_GRAY)
				.build());
		}

		if (musicTrackerConfig.showLocationOverlay())
		{
			panelComponent.getChildren().add(LineComponent.builder().left("Location:").leftColor(Color.WHITE).build());
			panelComponent.getChildren().add(LineComponent.builder()
				.left(currentMusicTrack.getLocation() != null ? currentMusicTrack.getLocation() : "Gielinor")
				.leftColor(Color.LIGHT_GRAY)
				.build());
		}

		SpecialTrackHandler specialTrackHandler = SpecialTrackRegistry.getHandler(currentMusicTrack, currentRoute);

		if (musicTrackerConfig.showQuestOverlay())
		{
			requirementSectionRenderer.renderQuestSection(panelComponent, musicTrackerPlugin,
				specialTrackHandler.getDynamicQuest(currentMusicTrack, currentRoute, musicTrackerPlugin), currentRoute);
		}

		if (musicTrackerConfig.showItemsOverlay())
		{
			requirementSectionRenderer.renderRequirementList(
				panelComponent,
				"Items Required:",
				specialTrackHandler.getDynamicItems(currentMusicTrack, currentRoute, musicTrackerPlugin),
				currentRoute.getItems(),
				itemRequirement -> resolveItemDisplayText(itemRequirement),
				musicTrackerPlugin::playerHasItem,
				ColorScheme.PROGRESS_ERROR_COLOR,
				ColorScheme.PROGRESS_ERROR_COLOR,
				ItemRequirement::hasItem,
				itemRequirement -> resolveItemRequirementColor(itemRequirement, ColorScheme.PROGRESS_ERROR_COLOR));
		}

		if (musicTrackerConfig.recommendedItemsOverlay())
		{
			requirementSectionRenderer.renderRequirementList(
				panelComponent,
				"Items Recommended:",
				specialTrackHandler.getDynamicItemRecommendations(currentMusicTrack, currentRoute, musicTrackerPlugin),
				currentRoute.getRecommendedItems(),
				itemRequirement -> resolveItemDisplayText(itemRequirement),
				musicTrackerPlugin::playerHasItem,
				ColorScheme.PROGRESS_ERROR_COLOR,
				ColorScheme.PROGRESS_INPROGRESS_COLOR,
				ItemRequirement::hasItem,
				itemRequirement -> resolveItemRequirementColor(itemRequirement, ColorScheme.PROGRESS_ERROR_COLOR));
		}

		if (musicTrackerConfig.showLevelsOverlay())
		{
			requirementSectionRenderer.renderRequirementList(
				panelComponent,
				"Levels Required:",
				specialTrackHandler.getDynamicLevels(currentMusicTrack, currentRoute, musicTrackerPlugin),
				currentRoute.getLevels(),
				this::formatLevelRequirement,
				levelRequirement -> client.getRealSkillLevel(levelRequirement.getSkill()) >= levelRequirement.getLevel(),
				ColorScheme.PROGRESS_ERROR_COLOR,
				ColorScheme.PROGRESS_ERROR_COLOR);
		}

		if (musicTrackerConfig.recommendedLevelsOverlay())
		{
			requirementSectionRenderer.renderRequirementList(
				panelComponent,
				"Levels Recommended:",
				specialTrackHandler.getDynamicLevelRecommendations(currentMusicTrack, currentRoute, musicTrackerPlugin),
				currentRoute.getRecommendedLevels(),
				this::formatLevelRequirement,
				levelRequirement -> client.getRealSkillLevel(levelRequirement.getSkill()) >= levelRequirement.getLevel(),
				ColorScheme.PROGRESS_INPROGRESS_COLOR,
				ColorScheme.PROGRESS_INPROGRESS_COLOR);
		}

		if (musicTrackerConfig.showNotesOverlay())
		{
			requirementSectionRenderer.renderNotesSection(panelComponent,
				specialTrackHandler.getDynamicNotes(currentMusicTrack, currentRoute, musicTrackerPlugin), currentRoute);
		}

		if (musicTrackerConfig.showUnlockHintOverlay())
		{
			renderUnlockHintSection(currentMusicTrack);
		}

		if (musicTrackerConfig.showDistanceOverlay())
		{
			renderDistanceSection(currentMusicTrack);
		}

		if (musicTrackerConfig.showNextTrackOverlay())
		{
			renderNextTrackSection(currentMusicTrack);
		}
	}

	private void renderNoRouteTrackDetails(MusicTrack currentMusicTrack)
	{
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Tracking:")
			.right(currentMusicTrack.getTitle())
			.leftColor(Color.WHITE)
			.rightColor(new Color(0, 176, 255))
			.build());

		if (musicTrackerConfig.showRegionOverlay())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Region:")
				.right(currentMusicTrack.getRegion() != null ? currentMusicTrack.getRegion() : "Unknown")
				.leftColor(Color.WHITE)
				.rightColor(Color.LIGHT_GRAY)
				.build());
		}

		if (musicTrackerConfig.showLocationOverlay())
		{
			panelComponent.getChildren().add(LineComponent.builder().left("Location:").leftColor(Color.WHITE).build());
			panelComponent.getChildren().add(LineComponent.builder()
				.left(currentMusicTrack.getLocation() != null ? currentMusicTrack.getLocation() : "Gielinor")
				.leftColor(Color.LIGHT_GRAY)
				.build());
		}

		if (musicTrackerConfig.showQuestOverlay())
		{
			renderNoRouteQuestSection(currentMusicTrack);
		}

		if (musicTrackerConfig.showUnlockHintOverlay())
		{
			renderUnlockHintSection(currentMusicTrack);
		}
	}

	private void renderNoRouteQuestSection(MusicTrack currentMusicTrack)
	{
		Quest requiredQuest = currentMusicTrack.getEffectiveUnlockQuest(null);
		if (requiredQuest == null)
		{
			return;
		}

		requirementSectionRenderer.addSpace(panelComponent);
		panelComponent.getChildren().add(LineComponent.builder().left("Quest Required:").leftColor(Color.WHITE).build());

		QuestState questState = musicTrackerPlugin.getPlayerState().getCachedQuestState(requiredQuest);

		Color questLineColor = questState == QuestState.FINISHED
			? ColorScheme.PROGRESS_COMPLETE_COLOR
			: ColorScheme.PROGRESS_ERROR_COLOR;
		panelComponent.getChildren().add(LineComponent.builder().left(requiredQuest.getName()).leftColor(questLineColor).build());
	}

	private String formatLevelRequirement(LevelRequirement levelRequirement)
	{
		return levelRequirement.getLevel() + " " + levelRequirement.getSkill().getName();
	}

	private String resolveItemDisplayText(ItemRequirement itemRequirement)
	{
		String displayText = itemRequirement.getDisplayText(musicTrackerPlugin.getItemManager());
		return itemRequirement.isEquipped() ? displayText + " (Equipped)" : displayText;
	}

	private Color resolveItemRequirementColor(ItemRequirement itemRequirement, Color unsatisfiedColor)
	{
		if (!itemRequirement.isEquipped())
		{
			return musicTrackerPlugin.playerHasItem(itemRequirement) ? ColorScheme.PROGRESS_COMPLETE_COLOR : unsatisfiedColor;
		}

		if (musicTrackerPlugin.playerHasItemEquipped(itemRequirement))
		{
			return ColorScheme.PROGRESS_COMPLETE_COLOR;
		}

		if (musicTrackerPlugin.playerHasItem(itemRequirement))
		{
			return ColorScheme.PROGRESS_INPROGRESS_COLOR;
		}

		return unsatisfiedColor;
	}

	private void renderUnlockHintSection(MusicTrack currentMusicTrack)
	{
		String unlockHintText = currentMusicTrack.getOverlayUnlockHintText();
		if (unlockHintText == null)
		{
			return;
		}
		requirementSectionRenderer.addSpace(panelComponent);
		panelComponent.getChildren().add(LineComponent.builder().left("Unlock Hint:").leftColor(Color.WHITE).build());
		panelComponent.getChildren().add(LineComponent.builder().left(unlockHintText).leftColor(Color.LIGHT_GRAY).build());
	}

	private void renderDistanceSection(MusicTrack currentMusicTrack)
	{
		WorldPoint targetWorldPoint = currentMusicTrack.getDestinationForStage(musicTrackerPlugin.getTrackNavigator().getCurrentStage());
		if (targetWorldPoint == null)
		{
			return;
		}

		int distanceInTiles = client.getLocalPlayer().getWorldLocation().distanceTo(targetWorldPoint);
		if (distanceInTiles <= 0 || distanceInTiles == Integer.MAX_VALUE)
		{
			return;
		}

		requirementSectionRenderer.addSpace(panelComponent);
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Distance:")
			.right(distanceInTiles + " tiles")
			.leftColor(Color.WHITE)
			.rightColor(Color.CYAN)
			.build());
	}

	private MusicTrack getCachedNextSuggestedTrack(MusicTrack currentMusicTrack)
	{
		int currentTick = client.getTickCount();
		if (currentTick == cachedNextSuggestedTrackAtTick && currentMusicTrack == cachedNextSuggestedTrackForCurrentTrack)
		{
			return cachedNextSuggestedTrack;
		}

		cachedNextSuggestedTrack = musicTrackerPlugin.getNextSuggestedTrack();
		cachedNextSuggestedTrackForCurrentTrack = currentMusicTrack;
		cachedNextSuggestedTrackAtTick = currentTick;
		return cachedNextSuggestedTrack;
	}

	private void renderNextTrackSection(MusicTrack currentMusicTrack)
	{
		try
		{
			MusicTrack nextSuggestedTrack = getCachedNextSuggestedTrack(currentMusicTrack);
			if (nextSuggestedTrack != null && nextSuggestedTrack.getTitle() != null && !nextSuggestedTrack.getTitle().equals(currentMusicTrack.getTitle()))
			{
				requirementSectionRenderer.addSpace(panelComponent);
				panelComponent.getChildren().add(LineComponent.builder()
					.left("Next:")
					.right(nextSuggestedTrack.getTitle())
					.leftColor(Color.WHITE)
					.rightColor(ColorScheme.PROGRESS_ERROR_COLOR)
					.build());
			}
		}
		catch (Exception exception)
		{
			log.debug("Error getting next track", exception);
		}
	}
}

package org.dejaq.plugins.musictracker.overlay;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Point;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseManager;
import net.runelite.client.ui.overlay.worldmap.WorldMapOverlay;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;
import net.runelite.client.util.ImageUtil;
import org.dejaq.plugins.musictracker.MusicTrack;
import org.dejaq.plugins.musictracker.MusicTrackManager;
import org.dejaq.plugins.musictracker.MusicTrackerConfig;
import org.dejaq.plugins.musictracker.MusicTrackerPlugin;
import org.dejaq.plugins.musictracker.state.TrackingStateService;
import org.dejaq.plugins.musictracker.track.UnlockType;

@Slf4j
@Singleton
public class MusicTrackWorldMapOverlay
{
	private static final String HARP_UNLOCKED_ICON_RESOURCE_NAME = "harp_unlocked.png";
	private static final String HARP_LOCKED_ICON_RESOURCE_NAME = "harp_locked.png";
	private static final int ICON_SIZE_PIXELS = 20;
	private static final int CLICK_RADIUS_PIXELS = 10;
	private static final int MAX_TOOLTIP_TITLE_COUNT = 4;

	private final MusicTrackManager musicTrackManager;
	private final MusicTrackerConfig musicTrackerConfig;
	private final TrackingStateService trackingStateService;
	private final WorldMapPointManager worldMapPointManager;
	private final WorldMapOverlay worldMapOverlay;
	private final MouseManager mouseManager;

	private final List<WorldMapIconGroup> activeIconGroups = new ArrayList<>();

	private MusicTrackerPlugin musicTrackerPlugin;
	private BufferedImage unlockedHarpIcon;
	private BufferedImage lockedHarpIcon;

	private final MouseAdapter worldMapMouseListener = new MouseAdapter()
	{
		@Override
		public MouseEvent mousePressed(MouseEvent mouseEvent)
		{
			return handleWorldMapMousePressed(mouseEvent);
		}
	};

	@Inject
	public MusicTrackWorldMapOverlay(MusicTrackManager musicTrackManager, MusicTrackerConfig musicTrackerConfig,
									 TrackingStateService trackingStateService, WorldMapPointManager worldMapPointManager,
									 WorldMapOverlay worldMapOverlay, MouseManager mouseManager)
	{
		this.musicTrackManager = musicTrackManager;
		this.musicTrackerConfig = musicTrackerConfig;
		this.trackingStateService = trackingStateService;
		this.worldMapPointManager = worldMapPointManager;
		this.worldMapOverlay = worldMapOverlay;
		this.mouseManager = mouseManager;
	}

	public void startUp(MusicTrackerPlugin musicTrackerPlugin)
	{
		this.musicTrackerPlugin = musicTrackerPlugin;
		mouseManager.registerMouseListener(worldMapMouseListener);
		loadHarpIcons();
		rebuildWorldMapPoints();
	}

	public void shutDown()
	{
		mouseManager.unregisterMouseListener(worldMapMouseListener);
		clearWorldMapPoints();
		this.musicTrackerPlugin = null;
	}

	public synchronized void rebuildWorldMapPoints()
	{
		clearWorldMapPoints();

		if (!musicTrackerConfig.showWorldMapOverlay())
		{
			return;
		}

		Map<WorldPoint, List<MusicTrack>> tracksByUnlockLocation = groupTracksByUnlockLocation();
		for (Map.Entry<WorldPoint, List<MusicTrack>> locationEntry : tracksByUnlockLocation.entrySet())
		{
			WorldPoint unlockLocation = locationEntry.getKey();
			List<MusicTrack> tracksAtLocation = locationEntry.getValue();

			WorldMapPoint worldMapPoint = createWorldMapPointForLocation(unlockLocation, tracksAtLocation);
			worldMapPointManager.add(worldMapPoint);
			activeIconGroups.add(new WorldMapIconGroup(unlockLocation, tracksAtLocation, worldMapPoint));
		}

		log.debug("Built {} music track world map icon group(s)", activeIconGroups.size());
	}

	public synchronized void clearWorldMapPoints()
	{
		for (WorldMapIconGroup iconGroup : activeIconGroups)
		{
			worldMapPointManager.remove(iconGroup.worldMapPoint);
		}
		activeIconGroups.clear();
	}

	private Map<WorldPoint, List<MusicTrack>> groupTracksByUnlockLocation()
	{
		Map<WorldPoint, List<MusicTrack>> tracksByUnlockLocation = new LinkedHashMap<>();

		for (MusicTrack musicTrack : musicTrackManager.getAllTracks())
		{
			UnlockType effectiveUnlockType = musicTrack.getUnlockType() != null ? musicTrack.getUnlockType() : UnlockType.NORMAL;
			if (effectiveUnlockType != UnlockType.NORMAL)
			{
				continue;
			}

			WorldPoint unlockLocation = musicTrack.getFirstStepDestination();
			if (unlockLocation == null || (unlockLocation.getX() == 0 && unlockLocation.getY() == 0))
			{
				continue;
			}

			tracksByUnlockLocation.computeIfAbsent(unlockLocation, key -> new ArrayList<>()).add(musicTrack);
		}

		return tracksByUnlockLocation;
	}

	private WorldMapPoint createWorldMapPointForLocation(WorldPoint unlockLocation, List<MusicTrack> tracksAtLocation)
	{
		boolean allTracksUnlocked = tracksAtLocation.stream()
			.allMatch(musicTrack -> trackingStateService.isTrackUnlocked(musicTrack.getTitle()));

		WorldMapPoint worldMapPoint = new WorldMapPoint(unlockLocation, allTracksUnlocked ? unlockedHarpIcon : lockedHarpIcon);
		worldMapPoint.setName("Music Tracker");
		worldMapPoint.setTooltip(buildTooltipText(tracksAtLocation));
		worldMapPoint.setJumpOnClick(false);
		worldMapPoint.setSnapToEdge(false);
		return worldMapPoint;
	}

	private String buildTooltipText(List<MusicTrack> tracksAtLocation)
	{
		if (tracksAtLocation.size() == 1)
		{
			MusicTrack onlyTrack = tracksAtLocation.get(0);
			String lockStateText = trackingStateService.isTrackUnlocked(onlyTrack.getTitle()) ? "Unlocked" : "Locked";
			return "Music Track: " + onlyTrack.getTitle() + " (" + lockStateText + ")";
		}

		List<MusicTrack> lockedFirstTracks = new ArrayList<>(tracksAtLocation);
		lockedFirstTracks.sort(Comparator.comparing(musicTrack -> trackingStateService.isTrackUnlocked(musicTrack.getTitle())));

		StringBuilder tooltipBuilder = new StringBuilder("Music Tracks:");
		int titleCountToShow = Math.min(MAX_TOOLTIP_TITLE_COUNT, lockedFirstTracks.size());
		for (int trackIndex = 0; trackIndex < titleCountToShow; trackIndex++)
		{
			tooltipBuilder.append("<br>").append(lockedFirstTracks.get(trackIndex).getTitle());
		}

		int remainingTrackCount = lockedFirstTracks.size() - titleCountToShow;
		if (remainingTrackCount > 0)
		{
			tooltipBuilder.append("<br>... and ").append(remainingTrackCount).append(" more");
		}

		return tooltipBuilder.toString();
	}

	private MouseEvent handleWorldMapMousePressed(MouseEvent mouseEvent)
	{
		if (mouseEvent.isConsumed() || !SwingUtilities.isLeftMouseButton(mouseEvent))
		{
			return mouseEvent;
		}

		if (musicTrackerPlugin == null || !musicTrackerConfig.showWorldMapOverlay() || !musicTrackerConfig.worldMapClickToTrack())
		{
			return mouseEvent;
		}

		WorldMapIconGroup clickedIconGroup = findIconGroupNearScreenPoint(mouseEvent.getX(), mouseEvent.getY());
		if (clickedIconGroup == null || clickedIconGroup.tracksAtLocation.isEmpty())
		{
			return mouseEvent;
		}

		MusicTrack firstTrackAtLocation = clickedIconGroup.tracksAtLocation.get(0);
		mouseEvent.consume();
		musicTrackerPlugin.selectTrack(firstTrackAtLocation);

		return mouseEvent;
	}

	private synchronized WorldMapIconGroup findIconGroupNearScreenPoint(int clickScreenX, int clickScreenY)
	{
		for (WorldMapIconGroup iconGroup : activeIconGroups)
		{
			Point iconScreenPoint = worldMapOverlay.mapWorldPointToGraphicsPoint(iconGroup.unlockLocation);
			if (iconScreenPoint == null)
			{
				continue;
			}

			double distanceToClick = Math.hypot(clickScreenX - iconScreenPoint.getX(), clickScreenY - iconScreenPoint.getY());
			if (distanceToClick <= CLICK_RADIUS_PIXELS)
			{
				return iconGroup;
			}
		}
		return null;
	}

	private void loadHarpIcons()
	{
		unlockedHarpIcon = loadHarpIcon(HARP_UNLOCKED_ICON_RESOURCE_NAME, true);
		lockedHarpIcon = loadHarpIcon(HARP_LOCKED_ICON_RESOURCE_NAME, false);
	}

	private BufferedImage loadHarpIcon(String resourceName, boolean unlockedVariant)
	{
		BufferedImage loadedHarpIcon = ImageUtil.loadImageResource(MusicTrackerPlugin.class, resourceName);
		if (loadedHarpIcon != null)
		{
			return ImageUtil.resizeImage(loadedHarpIcon, ICON_SIZE_PIXELS, ICON_SIZE_PIXELS);
		}

		log.warn("Could not load world map icon resource '{}', using a generated fallback icon", resourceName);
		return buildFallbackHarpIcon(unlockedVariant);
	}

	private BufferedImage buildFallbackHarpIcon(boolean unlockedVariant)
	{
		BufferedImage fallbackIcon = new BufferedImage(ICON_SIZE_PIXELS, ICON_SIZE_PIXELS, BufferedImage.TYPE_INT_ARGB);
		Graphics2D fallbackGraphics = fallbackIcon.createGraphics();
		fallbackGraphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		fallbackGraphics.setColor(unlockedVariant ? new Color(40, 170, 60) : new Color(210, 40, 40));
		fallbackGraphics.fillOval(1, 1, ICON_SIZE_PIXELS - 2, ICON_SIZE_PIXELS - 2);

		fallbackGraphics.setColor(Color.WHITE);
		fallbackGraphics.drawLine(ICON_SIZE_PIXELS / 3, ICON_SIZE_PIXELS / 2, ICON_SIZE_PIXELS - ICON_SIZE_PIXELS / 3, ICON_SIZE_PIXELS / 2);

		fallbackGraphics.dispose();
		return fallbackIcon;
	}

	private static final class WorldMapIconGroup
	{
		private final WorldPoint unlockLocation;
		private final List<MusicTrack> tracksAtLocation;
		private final WorldMapPoint worldMapPoint;

		private WorldMapIconGroup(WorldPoint unlockLocation, List<MusicTrack> tracksAtLocation, WorldMapPoint worldMapPoint)
		{
			this.unlockLocation = unlockLocation;
			this.tracksAtLocation = tracksAtLocation;
			this.worldMapPoint = worldMapPoint;
		}
	}
}

package org.dejaq.plugins.musictracker.overlay.components;

import java.awt.Color;
import java.util.List;
import java.util.function.Function;
import java.util.function.Predicate;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import org.dejaq.plugins.musictracker.MusicTrackerPlugin;
import org.dejaq.plugins.musictracker.quest.QuestState;
import org.dejaq.plugins.musictracker.requirement.DynamicRequirement;
import org.dejaq.plugins.musictracker.track.Route;

public class RequirementSectionRenderer
{
	public <T> void renderRequirementList(
		PanelComponent panelComponent,
		String sectionHeaderText,
		List<DynamicRequirement<T>> dynamicRequirements,
		List<T> staticRequirements,
		Function<T, String> displayTextResolver,
		Predicate<T> satisfactionChecker,
		Color unsatisfiedColorWhenRequirementKnown,
		Color unsatisfiedColorWhenRequirementUnknown)
	{
		renderRequirementList(panelComponent, sectionHeaderText, dynamicRequirements, staticRequirements,
			displayTextResolver, satisfactionChecker, unsatisfiedColorWhenRequirementKnown, unsatisfiedColorWhenRequirementUnknown,
			staticRequirement -> true, null);
	}

	public <T> void renderRequirementList(
		PanelComponent panelComponent,
		String sectionHeaderText,
		List<DynamicRequirement<T>> dynamicRequirements,
		List<T> staticRequirements,
		Function<T, String> displayTextResolver,
		Predicate<T> satisfactionChecker,
		Color unsatisfiedColorWhenRequirementKnown,
		Color unsatisfiedColorWhenRequirementUnknown,
		Predicate<T> hasRealBackingData)
	{
		renderRequirementList(panelComponent, sectionHeaderText, dynamicRequirements, staticRequirements,
			displayTextResolver, satisfactionChecker, unsatisfiedColorWhenRequirementKnown, unsatisfiedColorWhenRequirementUnknown,
			hasRealBackingData, null);
	}

	public <T> void renderRequirementList(
		PanelComponent panelComponent,
		String sectionHeaderText,
		List<DynamicRequirement<T>> dynamicRequirements,
		List<T> staticRequirements,
		Function<T, String> displayTextResolver,
		Predicate<T> satisfactionChecker,
		Color unsatisfiedColorWhenRequirementKnown,
		Color unsatisfiedColorWhenRequirementUnknown,
		Predicate<T> hasRealBackingData,
		Function<T, Color> perRequirementColorResolver)
	{
		if (dynamicRequirements != null && !dynamicRequirements.isEmpty())
		{
			addSectionHeader(panelComponent, sectionHeaderText);
			for (DynamicRequirement<T> dynamicRequirement : dynamicRequirements)
			{
				Color lineColor = resolveDynamicRequirementColor(dynamicRequirement, satisfactionChecker,
					unsatisfiedColorWhenRequirementKnown, unsatisfiedColorWhenRequirementUnknown, perRequirementColorResolver);
				addLine(panelComponent, dynamicRequirement.getDisplayText(), lineColor);
			}
			return;
		}

		if (staticRequirements == null || staticRequirements.isEmpty())
		{
			return;
		}

		addSectionHeader(panelComponent, sectionHeaderText);
		for (T staticRequirement : staticRequirements)
		{
			Color lineColor;
			if (!hasRealBackingData.test(staticRequirement))
			{
				lineColor = ColorScheme.TEXT_COLOR;
			}
			else if (perRequirementColorResolver != null && perRequirementColorResolver.apply(staticRequirement) != null)
			{
				lineColor = perRequirementColorResolver.apply(staticRequirement);
			}
			else
			{
				boolean isSatisfied = satisfactionChecker.test(staticRequirement);
				lineColor = isSatisfied ? ColorScheme.PROGRESS_COMPLETE_COLOR : unsatisfiedColorWhenRequirementKnown;
			}
			addLine(panelComponent, displayTextResolver.apply(staticRequirement), lineColor);
		}
	}

	private <T> Color resolveDynamicRequirementColor(
		DynamicRequirement<T> dynamicRequirement,
		Predicate<T> satisfactionChecker,
		Color unsatisfiedColorWhenRequirementKnown,
		Color unsatisfiedColorWhenRequirementUnknown,
		Function<T, Color> perRequirementColorResolver)
	{
		if (dynamicRequirement.getColor() != null)
		{
			return dynamicRequirement.getColor();
		}
		if (dynamicRequirement.getRequirement() != null)
		{
			if (perRequirementColorResolver != null && perRequirementColorResolver.apply(dynamicRequirement.getRequirement()) != null)
			{
				return perRequirementColorResolver.apply(dynamicRequirement.getRequirement());
			}
			boolean isSatisfied = satisfactionChecker.test(dynamicRequirement.getRequirement());
			return isSatisfied ? ColorScheme.PROGRESS_COMPLETE_COLOR : unsatisfiedColorWhenRequirementKnown;
		}
		return unsatisfiedColorWhenRequirementUnknown;
	}

	public void renderQuestSection(PanelComponent panelComponent, MusicTrackerPlugin musicTrackerPlugin, DynamicRequirement<String> dynamicQuestRequirement, Route currentRoute)
	{
		boolean hasDynamicQuestText = dynamicQuestRequirement != null
			&& dynamicQuestRequirement.getDisplayText() != null
			&& !dynamicQuestRequirement.getDisplayText().isBlank();

		if (hasDynamicQuestText)
		{
			addSectionHeader(panelComponent, "Quest Required:");
			Color questLineColor = dynamicQuestRequirement.getColor() != null
				? dynamicQuestRequirement.getColor()
				: resolveStaticQuestColor(musicTrackerPlugin, currentRoute);
			addLine(panelComponent, dynamicQuestRequirement.getDisplayText(), questLineColor);
			return;
		}

		if (currentRoute.getQuest() != null)
		{
			addSectionHeader(panelComponent, "Quest Required:");
			addLine(panelComponent, currentRoute.getQuest().getName(), resolveStaticQuestColor(musicTrackerPlugin, currentRoute));
		}
	}

	private Color resolveStaticQuestColor(MusicTrackerPlugin musicTrackerPlugin, Route currentRoute)
	{
		if (currentRoute.getQuest() == null)
		{
			return ColorScheme.PROGRESS_ERROR_COLOR;
		}

		QuestState questState = musicTrackerPlugin.getPlayerState()
			.getCachedQuestState(currentRoute.getQuest());

		return questState == QuestState.FINISHED
			? ColorScheme.PROGRESS_COMPLETE_COLOR
			: ColorScheme.PROGRESS_ERROR_COLOR;
	}

	public void renderNotesSection(PanelComponent panelComponent, DynamicRequirement<String> dynamicNotesRequirement, Route currentRoute)
	{
		String notesText = null;
		Color notesColor = Color.LIGHT_GRAY;

		boolean hasDynamicNotesText = dynamicNotesRequirement != null
			&& dynamicNotesRequirement.getDisplayText() != null
			&& !dynamicNotesRequirement.getDisplayText().isBlank();

		if (hasDynamicNotesText)
		{
			notesText = dynamicNotesRequirement.getDisplayText();
			if (dynamicNotesRequirement.getColor() != null)
			{
				notesColor = dynamicNotesRequirement.getColor();
			}
		}
		else if (currentRoute.getNotes() != null && !currentRoute.getNotes().isBlank())
		{
			notesText = currentRoute.getNotes();
		}

		if (notesText != null)
		{
			addSectionHeader(panelComponent, "Notes:");
			addLine(panelComponent, notesText, notesColor);
		}
	}

	private void addSectionHeader(PanelComponent panelComponent, String headerText)
	{
		addSpace(panelComponent);
		panelComponent.getChildren().add(LineComponent.builder().left(headerText).leftColor(Color.WHITE).build());
	}

	private void addLine(PanelComponent panelComponent, String text, Color color)
	{
		panelComponent.getChildren().add(LineComponent.builder().left(text).leftColor(color).build());
	}

	public void addSpace(PanelComponent panelComponent)
	{
		panelComponent.getChildren().add(LineComponent.builder().left(" ").build());
	}
}

