package org.dejaq.plugins.musictracker.state;

import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import org.dejaq.plugins.musictracker.quest.Quest;
import org.dejaq.plugins.musictracker.quest.QuestState;

@Singleton
public class PlayerState
{
	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;

	@Getter
	private final Map<Integer, Boolean> varbitData = new ConcurrentHashMap<>();

	@Getter
	@Setter
	private GameState gameState = GameState.LOGIN_SCREEN;

	private final Map<Integer, Integer> inventoryItemQuantities = new ConcurrentHashMap<>();
	private final Map<Integer, Integer> equipmentItemQuantities = new ConcurrentHashMap<>();

	private final Map<Skill, Integer> realSkillLevels = new ConcurrentHashMap<>();
	private final Map<Quest, QuestState> questStateCache = new ConcurrentHashMap<>();
	private final Set<Quest> questStatesInFlight = ConcurrentHashMap.newKeySet();

	public void refreshTrackingVarbits()
	{
		varbitData.put(VarbitID.MUSIC_UNLOCK_TEXT_TOGGLE, client.getVarbitValue(VarbitID.MUSIC_UNLOCK_TEXT_TOGGLE) == 0);
		varbitData.put(VarbitID.MUSIC_AREA_MODE, client.getVarbitValue(VarbitID.MUSIC_AREA_MODE) == 0);
	}

	public boolean canTrackMusic()
	{
		return varbitData.getOrDefault(VarbitID.MUSIC_UNLOCK_TEXT_TOGGLE, false)
			&& varbitData.getOrDefault(VarbitID.MUSIC_AREA_MODE, false);
	}

	public void refreshItemQuantityCaches()
	{
		clientThread.invokeLater(() -> {
			inventoryItemQuantities.clear();
			equipmentItemQuantities.clear();

			ItemContainer inventoryItemContainer = client.getItemContainer(InventoryID.INV);
			if (inventoryItemContainer != null)
			{
				for (Item inventoryItem : inventoryItemContainer.getItems())
				{
					if (inventoryItem != null && inventoryItem.getId() > 0)
					{
						inventoryItemQuantities.merge(inventoryItem.getId(), inventoryItem.getQuantity(), Integer::sum);
					}
				}
			}

			ItemContainer equippedItemContainer = client.getItemContainer(InventoryID.WORN);
			if (equippedItemContainer != null)
			{
				for (Item equippedItem : equippedItemContainer.getItems())
				{
					if (equippedItem != null && equippedItem.getId() > 0)
					{
						equipmentItemQuantities.merge(equippedItem.getId(), equippedItem.getQuantity(), Integer::sum);
					}
				}
			}
		});
	}

	public void clearItemQuantityCaches()
	{
		inventoryItemQuantities.clear();
		equipmentItemQuantities.clear();
	}

	public int getItemQuantity(int itemId)
	{
		return inventoryItemQuantities.getOrDefault(itemId, 0) + equipmentItemQuantities.getOrDefault(itemId, 0);
	}

	public Set<Integer> getInventoryItemIds()
	{
		return Set.copyOf(inventoryItemQuantities.keySet());
	}

	public Set<Integer> getEquipmentItemIds()
	{
		return Set.copyOf(equipmentItemQuantities.keySet());
	}

	public boolean hasItemQuantity(int itemId, int requiredQuantity)
	{
		int totalQuantity = inventoryItemQuantities.getOrDefault(itemId, 0) + equipmentItemQuantities.getOrDefault(itemId, 0);
		return totalQuantity >= requiredQuantity;
	}

	public boolean hasItemFromCollection(List<Integer> candidateItemIds, int requiredQuantity)
	{
		int totalQuantity = 0;
		for (int candidateItemId : candidateItemIds)
		{
			totalQuantity += inventoryItemQuantities.getOrDefault(candidateItemId, 0);
			totalQuantity += equipmentItemQuantities.getOrDefault(candidateItemId, 0);
		}
		return totalQuantity >= requiredQuantity;
	}

	public boolean hasItemFromCollection(List<Integer> candidateItemIds)
	{
		return hasItemFromCollection(candidateItemIds, 1);
	}

	public boolean hasEquippedItemQuantity(int itemId, int requiredQuantity)
	{
		return equipmentItemQuantities.getOrDefault(itemId, 0) >= requiredQuantity;
	}

	public boolean hasEquippedItemFromCollection(List<Integer> candidateItemIds, int requiredQuantity)
	{
		int totalQuantity = 0;
		for (int candidateItemId : candidateItemIds)
		{
			totalQuantity += equipmentItemQuantities.getOrDefault(candidateItemId, 0);
		}
		return totalQuantity >= requiredQuantity;
	}

	public boolean hasEquippedItemFromCollection(List<Integer> candidateItemIds)
	{
		return hasEquippedItemFromCollection(candidateItemIds, 1);
	}

	public void updateRealSkillLevel(Skill skill, int realLevel)
	{
		realSkillLevels.put(skill, realLevel);
	}

	public int getCachedRealSkillLevel(Skill skill)
	{
		return realSkillLevels.getOrDefault(skill, 1);
	}

	public QuestState getCachedQuestState(Quest quest, Runnable onCacheUpdated)
	{
		QuestState cachedQuestState = questStateCache.get(quest);
		if (cachedQuestState == null)
		{
			refreshQuestStateAsync(quest, onCacheUpdated);
			return QuestState.NOT_STARTED;
		}
		return cachedQuestState;
	}

	public QuestState getCachedQuestState(Quest quest)
	{
		return getCachedQuestState(quest, null);
	}

	private void refreshQuestStateAsync(Quest quest, Runnable onCacheUpdated)
	{
		if (!questStatesInFlight.add(quest))
		{
			return;
		}

		clientThread.invokeLater(() -> {
			questStateCache.put(quest, quest.getState(client));
			questStatesInFlight.remove(quest);
			if (onCacheUpdated != null)
			{
				SwingUtilities.invokeLater(onCacheUpdated);
			}
		});
	}

	public void reset()
	{
		gameState = GameState.LOGIN_SCREEN;
		clearItemQuantityCaches();
		questStateCache.clear();
		questStatesInFlight.clear();
		realSkillLevels.clear();
	}
}

package org.dejaq.plugins.musictracker.state;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import org.dejaq.plugins.musictracker.MusicTrackerConfig;

@Slf4j
@Singleton
public class TrackingStateService
{
	private static final String CONFIG_GROUP_NAME = "music-tracker";
	private static final String SKIPPED_TRACKS_CONFIG_KEY = "skippedTracks";
	private static final String DEFAULT_STARTING_REGION_NAME = "Misthalin";

	@Inject
	private ConfigManager configManager;
	@Inject
	private MusicTrackerConfig musicTrackerConfig;
	@Inject
	private Gson gson;

	@Setter
	@Getter
	private boolean trackingActive = false;

	@Setter
	@Getter
	private String currentRegionName = DEFAULT_STARTING_REGION_NAME;

	private final Set<String> unlockedTrackTitles = ConcurrentHashMap.newKeySet();
	private final Set<String> fakeUnlockedTrackTitles = ConcurrentHashMap.newKeySet();
	@Getter
	private final Set<String> skippedTrackTitles = ConcurrentHashMap.newKeySet();

	public Set<String> getCurrentUnlockedTrackTitles()
	{
		return musicTrackerConfig.lockedTracks() ? fakeUnlockedTrackTitles : unlockedTrackTitles;
	}

	public boolean isTrackUnlocked(String trackTitle)
	{
		return getCurrentUnlockedTrackTitles().contains(trackTitle);
	}

	public boolean recordTrackUnlocked(String trackTitle)
	{
		return getCurrentUnlockedTrackTitles().add(trackTitle);
	}

	public void clearUnlockedTracks()
	{
		getCurrentUnlockedTrackTitles().clear();
	}

	public void resetAccountScopedState()
	{
		unlockedTrackTitles.clear();
		fakeUnlockedTrackTitles.clear();
	}

	public boolean isTrackSkipped(String trackTitle)
	{
		return skippedTrackTitles.contains(trackTitle);
	}

	public void setTrackSkipped(String trackTitle, boolean skipped)
	{
		boolean changed = skipped ? skippedTrackTitles.add(trackTitle) : skippedTrackTitles.remove(trackTitle);
		if (changed)
		{
			persistSkippedTracksIfEnabled();
		}
	}

	public void clearSkippedTracks()
	{
		skippedTrackTitles.clear();
		persistSkippedTracksIfEnabled();
	}

	public void disableAndWipeSkippedTracks()
	{
		skippedTrackTitles.clear();
		configManager.setConfiguration(CONFIG_GROUP_NAME, SKIPPED_TRACKS_CONFIG_KEY, "");
	}

	public void loadSkippedTracksFromConfig()
	{
		if (!musicTrackerConfig.saveSkippedTracks())
		{
			skippedTrackTitles.clear();
			return;
		}

		String persistedSkippedTracksJson = musicTrackerConfig.skippedTracks();
		if (persistedSkippedTracksJson == null || persistedSkippedTracksJson.isBlank())
		{
			skippedTrackTitles.clear();
			return;
		}

		try
		{
			Type skippedTrackSetType = new TypeToken<Set<String>>()
			{
			}.getType();
			Set<String> loadedSkippedTrackTitles = gson.fromJson(persistedSkippedTracksJson, skippedTrackSetType);
			skippedTrackTitles.clear();
			if (loadedSkippedTrackTitles != null)
			{
				skippedTrackTitles.addAll(loadedSkippedTrackTitles);
			}
		}
		catch (Exception exception)
		{
			log.warn("Failed to load skipped tracks", exception);
		}
	}

	private void persistSkippedTracksIfEnabled()
	{
		if (!musicTrackerConfig.saveSkippedTracks())
		{
			return;
		}
		try
		{
			configManager.setConfiguration(CONFIG_GROUP_NAME, SKIPPED_TRACKS_CONFIG_KEY, gson.toJson(skippedTrackTitles));
		}
		catch (Exception exception)
		{
			log.warn("Failed to save skipped tracks", exception);
		}
	}
}

package org.dejaq.plugins.musictracker.state;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.function.IntConsumer;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.util.Text;
import org.dejaq.plugins.musictracker.MusicTrack;
import org.dejaq.plugins.musictracker.MusicTrackerConfig;
import org.dejaq.plugins.musictracker.MusicTrackManager;

@Singleton
public class UnlockDetectionService
{
	public interface UnlockListener
	{
		void onTrackUnlocked(MusicTrack unlockedMusicTrack);
	}

	private static final Pattern UNLOCK_CHAT_MESSAGE_PATTERN =
		Pattern.compile("unlocked (?:a new )?music track[:\\s]+(?:<col=[^>]+>)?([^<]+)");

	// Green text - set by the game's music tab script on unlocked track rows
	private static final int UNLOCKED_TRACK_WIDGET_TEXT_COLOR = 0x0DC10D;
	// Cyan text - set by the game's music tab script on the currently playing track row
	private static final int NOW_PLAYING_WIDGET_TEXT_COLOR = 0x3CE6E6;

	private static final long SYNC_BATCH_TIME_BUDGET_NANOS = 1_000_000L;

	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;
	@Inject
	private MusicTrackManager musicTrackManager;
	@Inject
	private TrackingStateService trackingStateService;
	@Inject
	private MusicTrackerConfig musicTrackerConfig;

	private String lastKnownNowPlayingTrackTitle;

	@Getter
	private boolean musicTabSyncInProgress;
	private List<Widget> pendingSyncWidgets;
	private int pendingSyncWidgetIndex;
	private Map<String, MusicTrack> pendingSyncTrackTitleIndex;
	private int pendingSyncNewlyUnlockedCount;
	private UnlockListener pendingSyncListener;
	private IntConsumer pendingSyncCompletionCallback;

	public void handleChatMessage(ChatMessage chatMessageEvent, UnlockListener unlockListener)
	{
		if (chatMessageEvent.getType() != ChatMessageType.GAMEMESSAGE && chatMessageEvent.getType() != ChatMessageType.SPAM)
		{
			return;
		}

		Matcher unlockMessageMatcher = UNLOCK_CHAT_MESSAGE_PATTERN.matcher(chatMessageEvent.getMessage());
		if (unlockMessageMatcher.find())
		{
			recordUnlockedTrackByTitle(unlockMessageMatcher.group(1).trim(), unlockListener);
		}
	}

	public boolean isMusicTabOpen()
	{
		Widget trackListWidget = client.getWidget(InterfaceID.Music.SCROLLABLE);
		if (trackListWidget != null && !trackListWidget.isHidden()
			&& trackListWidget.getChildren() != null && trackListWidget.getChildren().length > 0)
		{
			return true;
		}

		Widget trackListBackgroundWidget = client.getWidget(InterfaceID.Music.BACKGROUND);
		if (trackListBackgroundWidget != null && !trackListBackgroundWidget.isHidden())
		{
			return true;
		}

		Widget musicTabContentsWidget = client.getWidget(InterfaceID.Music.CONTENTS);
		return musicTabContentsWidget != null && !musicTabContentsWidget.isHidden();
	}

	public void pollNowPlayingTrack(UnlockListener unlockListener)
	{
		Widget nowPlayingWidget = client.getWidget(InterfaceID.Music.NOW_PLAYING_TEXT);
		if (nowPlayingWidget == null || nowPlayingWidget.getText() == null)
		{
			return;
		}

		String nowPlayingTrackTitle = Text.removeTags(nowPlayingWidget.getText()).trim();
		if (nowPlayingTrackTitle.isBlank() || nowPlayingTrackTitle.equalsIgnoreCase(lastKnownNowPlayingTrackTitle))
		{
			return;
		}

		lastKnownNowPlayingTrackTitle = nowPlayingTrackTitle;

		if (!trackingStateService.isTrackUnlocked(nowPlayingTrackTitle))
		{
			recordUnlockedTrackByTitle(nowPlayingTrackTitle, unlockListener);
		}
	}

	public void beginMusicTabSync(UnlockListener unlockListener, IntConsumer onSyncComplete)
	{
		if (musicTabSyncInProgress || musicTrackerConfig.lockedTracks())
		{
			return;
		}

		pendingSyncWidgets = flattenMusicTabTrackWidgets();
		pendingSyncWidgetIndex = 0;
		pendingSyncTrackTitleIndex = musicTrackManager.buildTrackTitleIndex();
		pendingSyncNewlyUnlockedCount = 0;
		pendingSyncListener = unlockListener;
		pendingSyncCompletionCallback = onSyncComplete;
		musicTabSyncInProgress = true;

		processSyncBatch();
	}

	private List<Widget> flattenMusicTabTrackWidgets()
	{
		List<Widget> flattenedWidgets = new ArrayList<>();

		Widget trackListRoot = client.getWidget(InterfaceID.Music.JUKEBOX);
		if (trackListRoot == null)
		{
			return flattenedWidgets;
		}

		for (Widget categoryContainer : getWidgetNull(trackListRoot.getChildren()))
		{
			flattenedWidgets.add(categoryContainer);
			addAllNonNull(flattenedWidgets, categoryContainer.getChildren());
			addAllNonNull(flattenedWidgets, categoryContainer.getDynamicChildren());
		}

		return flattenedWidgets;
	}

	private static Widget[] getWidgetNull(Widget[] widgets)
	{
		return widgets != null ? widgets : new Widget[0];
	}

	private static void addAllNonNull(List<Widget> destination, Widget[] widgets)
	{
		if (widgets == null)
		{
			return;
		}
		for (Widget widget : widgets)
		{
			if (widget != null)
			{
				destination.add(widget);
			}
		}
	}

	private void processSyncBatch()
	{
		long batchStartNanos = System.nanoTime();

		while (pendingSyncWidgetIndex < pendingSyncWidgets.size())
		{
			Widget widget = pendingSyncWidgets.get(pendingSyncWidgetIndex);
			pendingSyncWidgetIndex++;

			pendingSyncNewlyUnlockedCount += synchronizeUnlockedTrackWidget(widget, pendingSyncTrackTitleIndex, pendingSyncListener);

			if (System.nanoTime() - batchStartNanos >= SYNC_BATCH_TIME_BUDGET_NANOS)
			{
				break;
			}
		}

		if (pendingSyncWidgetIndex < pendingSyncWidgets.size())
		{
			clientThread.invokeLater(this::processSyncBatch);
			return;
		}

		int totalNewlyUnlockedCount = pendingSyncNewlyUnlockedCount;
		IntConsumer completionCallback = pendingSyncCompletionCallback;

		musicTabSyncInProgress = false;
		pendingSyncWidgets = null;
		pendingSyncTrackTitleIndex = null;
		pendingSyncListener = null;
		pendingSyncCompletionCallback = null;

		completionCallback.accept(totalNewlyUnlockedCount);
	}

	private int synchronizeUnlockedTrackWidget(Widget trackEntryWidget, Map<String, MusicTrack> trackTitleIndex, UnlockListener unlockListener)
	{
		if (trackEntryWidget.getTextColor() != UNLOCKED_TRACK_WIDGET_TEXT_COLOR
			&& trackEntryWidget.getTextColor() != NOW_PLAYING_WIDGET_TEXT_COLOR)
		{
			return 0;
		}

		String widgetText = trackEntryWidget.getText();
		if (widgetText == null || widgetText.isBlank())
		{
			return 0;
		}

		String trackTitle = Text.removeTags(widgetText).trim();
		MusicTrack matchingTrack = trackTitleIndex.get(MusicTrackManager.normalizeTrackTitleKey(trackTitle));

		if (matchingTrack == null || !trackingStateService.recordTrackUnlocked(matchingTrack.getTitle()))
		{
			return 0;
		}

		unlockListener.onTrackUnlocked(matchingTrack);
		return 1;
	}

	private void recordUnlockedTrackByTitle(String rawTrackTitle, UnlockListener unlockListener)
	{
		if (rawTrackTitle == null || rawTrackTitle.isBlank())
		{
			return;
		}

		musicTrackManager.findTrackByTitle(rawTrackTitle)
			.filter(matchingTrack -> trackingStateService.recordTrackUnlocked(matchingTrack.getTitle()))
			.ifPresent(unlockListener::onTrackUnlocked);
	}
}

