import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.coords.WorldPoint;

@Data
@AllArgsConstructor
public class MusicTrackEntityPoint
{

	private final int regionId;
	private final int worldX;
	private final int worldY;
	private final int plane;
	private final int entityId;
	private final String entity;
	private final InteractionType interactionType;

	@Getter
	@Setter
	private InteractionTarget interactionTarget;

	public static MusicTrackEntityPoint from(WorldPoint worldPoint, int entityId, InteractionType type)
	{
		return new MusicTrackEntityPoint(
			worldPoint.getRegionID(), worldPoint.getX(), worldPoint.getY(), worldPoint.getPlane(),
			entityId, null, type, null
		);
	}

	public static MusicTrackEntityPoint from(WorldPoint worldPoint, String entity, InteractionType type)
	{
		return new MusicTrackEntityPoint(
			worldPoint.getRegionID(), worldPoint.getX(), worldPoint.getY(), worldPoint.getPlane(),
			-1, entity, type, null
		);
	}

	public static MusicTrackEntityPoint from(WorldPoint worldPoint, InteractionTarget interaction)
	{
		if (interaction == null)
		{
			return new MusicTrackEntityPoint(
				worldPoint.getRegionID(), worldPoint.getX(), worldPoint.getY(), worldPoint.getPlane(),
				-1, null, null, null
			);
		}

		WorldPoint effectiveLocation = interaction.getLocation() != null
			? interaction.getLocation()
			: worldPoint;

		if (interaction.getEntityId() > 0)
		{
			return new MusicTrackEntityPoint(
				effectiveLocation.getRegionID(),
				effectiveLocation.getX(),
				effectiveLocation.getY(),
				effectiveLocation.getPlane(),
				interaction.getEntityId(),
				null,
				interaction.getType(),
				interaction
			);
		}
		else
		{
			return new MusicTrackEntityPoint(
				effectiveLocation.getRegionID(),
				effectiveLocation.getX(),
				effectiveLocation.getY(),
				effectiveLocation.getPlane(),
				-1,
				interaction.getEntity(),
				interaction.getType(),
				interaction
			);
		}
	}
}

package org.dejaq.plugins.musictracker.track;

import java.util.Locale;

public enum Region
{
	MISTHALIN,
	ASGARNIA,
	KANDARIN,
	KARAMJA,
	MORYTANIA,
	KHARIDIAN_DESERT,
	FREMENNIK_PROVINCE,
	TIRANNWN,
	WILDERNESS,
	GREAT_KOUREND,
	VARLAMORE,
	KEBOS_LOWLANDS,
	OTHER,
	UNKNOWN,
	QUESTS,
	HOLIDAY,
	SAILING;

	public String getDisplayName()
	{
		return formatWords(" ");
	}

	public String getResourceFileBaseName()
	{
		return formatWords("");
	}

	private String formatWords(String wordSeparator)
	{
		String[] words = name().toLowerCase(Locale.ROOT).split("_");
		StringBuilder formattedNameBuilder = new StringBuilder();

		for (int wordIndex = 0; wordIndex < words.length; wordIndex++)
		{
			if (words[wordIndex].isEmpty())
			{
				continue;
			}
			formattedNameBuilder.append(Character.toUpperCase(words[wordIndex].charAt(0)));
			if (words[wordIndex].length() > 1)
			{
				formattedNameBuilder.append(words[wordIndex].substring(1));
			}
			if (wordIndex < words.length - 1)
			{
				formattedNameBuilder.append(wordSeparator);
			}
		}

		return formattedNameBuilder.toString();
	}
}

