package org.dejaq.plugins.musictracker.track.special;

import java.util.List;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import org.dejaq.plugins.musictracker.MusicTrack;
import org.dejaq.plugins.musictracker.MusicTrackerPlugin;
import org.dejaq.plugins.musictracker.track.InteractionTarget;
import org.dejaq.plugins.musictracker.track.InteractionType;
import org.dejaq.plugins.musictracker.track.MusicTrackEntityPoint;
import org.dejaq.plugins.musictracker.track.Route;
import org.dejaq.plugins.musictracker.track.TrackStep;

@Slf4j
public class QuetzalTrackHandler implements SpecialTrackHandler
{
	public static final String TALKASTI_PEOPLE_TRACK = "The Talkasti People";
	public static final String UNDER_THE_MOUNTAIN_TRACK = "Under the Mountain";

	private static final List<String> QUETZAL_ROUTE_NAMES = List.of("Quetzal");

	private static final String RENU_ENTITY_NAME = "Renu";
	private static final String TRAVEL_ACTION = "Travel";
	private static final int LANDING_SITE_ARRIVAL_RADIUS = 4;
	private static final String OVER_THE_MOUNTAINS_TRACK_TITLE = "Over the Mountains";
	private static final int UNLOCK_DESTINATION_REVERT_RADIUS = 85;
	private static final String DATA_KEY_QUETZAL = "quetzal";

	private int cachedTick = -1;
	private int cachedStageIndex = -1;
	private List<MusicTrackEntityPoint> cachedHighlights;

	@Override
	public List<String> getHandledRouteNames()
	{
		return QUETZAL_ROUTE_NAMES;
	}

	@Override
	public List<SpecialEntity> getHandledEntities()
	{
		return List.of(SpecialEntity.QUETZAL);
	}

	@Override
	public Integer getForcedStageIndex(MusicTrack musicTrack, Route route, int currentStageIndex, WorldPoint currentPlayerLocation, MusicTrackerPlugin musicTrackerPlugin)
	{
		if (route == null || currentPlayerLocation == null)
		{
			return null;
		}

		Client client = musicTrackerPlugin.getClient();
		if (!client.isClientThread())
		{
			return null;
		}

		TrackStep currentTrackStep = route.getStep(currentStageIndex);

		if (isQuetzalTravelStep(currentTrackStep))
		{
			return resolveForwardAdvanceFromTravelStep(musicTrack, route, currentStageIndex, currentTrackStep, currentPlayerLocation, client);
		}

		return resolveBackwardRevertToTravelStep(musicTrack, route, currentStageIndex, currentPlayerLocation);
	}

	private Integer resolveForwardAdvanceFromTravelStep(MusicTrack musicTrack, Route route, int currentStageIndex, TrackStep currentTrackStep, WorldPoint currentPlayerLocation, Client client)
	{
		int nextStageIndex = currentStageIndex + 1;
		if (nextStageIndex >= route.getStepCount())
		{
			return null;
		}

		Quetzal arrivalTarget = resolveArrivalTarget(musicTrack, currentTrackStep, client);
		if (arrivalTarget == null)
		{
			return null;
		}

		WorldPoint landingSiteLocation = arrivalTarget.getLandingSiteLocation();
		boolean arrivedAtLandingSite = currentPlayerLocation.distanceTo(landingSiteLocation) <= LANDING_SITE_ARRIVAL_RADIUS;

		return arrivedAtLandingSite ? nextStageIndex : null;
	}

	private Integer resolveBackwardRevertToTravelStep(MusicTrack musicTrack, Route route, int currentStageIndex, WorldPoint currentPlayerLocation)
	{
		int previousStageIndex = currentStageIndex - 1;
		if (previousStageIndex < 0)
		{
			return null;
		}

		TrackStep previousTrackStep = route.getStep(previousStageIndex);
		if (!isQuetzalTravelStep(previousTrackStep))
		{
			return null;
		}

		TrackStep currentTrackStep = route.getStep(currentStageIndex);
		if (currentTrackStep == null || currentTrackStep.getDestination() == null)
		{
			return null;
		}

		WorldPoint unlockDestination = currentTrackStep.getDestination();
		boolean farFromUnlockDestination = currentPlayerLocation.distanceTo(unlockDestination) >
			(musicTrack.getTitle().equals(OVER_THE_MOUNTAINS_TRACK_TITLE) ? 120 : UNLOCK_DESTINATION_REVERT_RADIUS); // best we can do...

		return farFromUnlockDestination ? previousStageIndex : null;
	}

	private boolean isQuetzalTravelStep(TrackStep trackStep)
	{
		if (trackStep == null)
		{
			return false;
		}
		for (InteractionTarget interactionTarget : trackStep.getAllHighlights())
		{
			if (SpecialEntity.fromToken(interactionTarget.getEntity()) == SpecialEntity.QUETZAL)
			{
				return true;
			}
		}
		return false;
	}

	@Override
	public boolean hasVolatileDynamicHighlights(MusicTrack musicTrack, Route route, MusicTrackerPlugin musicTrackerPlugin)
	{
		return true;
	}

	@Override
	public List<MusicTrackEntityPoint> getDynamicEntityHighlights(MusicTrack musicTrack, Route route, TrackStep trackStep, int stageIndex, MusicTrackerPlugin musicTrackerPlugin)
	{
		if (route == null)
		{
			return null;
		}

		Client client = musicTrackerPlugin.getClient();
		if (!client.isClientThread())
		{
			log.warn("Quetzal getDynamicEntityHighlights called off the client thread; ignoring");
			return null;
		}

		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null)
		{
			return null;
		}

		if (!isQuetzalTravelStep(trackStep))
		{
			return null;
		}

		int currentTick = client.getTickCount();
		if (currentTick == cachedTick && stageIndex == cachedStageIndex && cachedHighlights != null)
		{
			return cachedHighlights;
		}

		boolean isVarbitGatedTrack = isVarbitGatedTrack(musicTrack);
		Quetzal departureQuetzal = resolveDepartureQuetzal(client, localPlayer.getWorldLocation());
		if (departureQuetzal == null)
		{
			cachedTick = currentTick;
			cachedStageIndex = stageIndex;
			cachedHighlights = null;
			return null;
		}

		musicTrackerPlugin.getTrackNavigator().getNavigationCoordinator().requestShortestPathTo(departureQuetzal.getLandingSiteLocation());

		String hintText;
		Quetzal arrivalTarget = resolveArrivalTarget(musicTrack, trackStep, client);
		String destinationName = arrivalTarget != null ? arrivalTarget.getDisplayName() : departureQuetzal.getDisplayName();
		String travelHint = TRAVEL_ACTION + " -> " + (TALKASTI_PEOPLE_TRACK.equals(musicTrack.getTitle())
			? Quetzal.TAL_TEKLAN : UNDER_THE_MOUNTAIN_TRACK.equals(musicTrack.getTitle())
			? Quetzal.THE_TEOMAT : destinationName);
		hintText = isVarbitGatedTrack ? travelHint : resolveJsonHint(trackStep, travelHint);

		cachedTick = currentTick;
		cachedStageIndex = stageIndex;
		cachedHighlights = buildRenuHighlight(departureQuetzal.getLandingSiteLocation(), hintText);
		return cachedHighlights;
	}

	@Override
	public void reset()
	{
		cachedTick = -1;
		cachedStageIndex = -1;
		cachedHighlights = null;
	}

	private boolean isVarbitGatedTrack(MusicTrack musicTrack)
	{
		if (musicTrack == null || musicTrack.getTitle() == null)
		{
			return false;
		}
		return musicTrack.getTitle().equalsIgnoreCase(TALKASTI_PEOPLE_TRACK)
			|| musicTrack.getTitle().equalsIgnoreCase(UNDER_THE_MOUNTAIN_TRACK);
	}

	private String resolveJsonHint(TrackStep trackStep, String fallbackHint)
	{
		if (trackStep == null)
		{
			return fallbackHint;
		}
		for (InteractionTarget interactionTarget : trackStep.getAllHighlights())
		{
			if (SpecialEntity.fromToken(interactionTarget.getEntity()) == SpecialEntity.QUETZAL
				&& interactionTarget.getHint() != null && !interactionTarget.getHint().isBlank())
			{
				return interactionTarget.getHint();
			}
		}
		return fallbackHint;
	}

	private Quetzal resolveDepartureQuetzal(Client client, WorldPoint playerLocation)
	{
		return findNearestAvailableQuetzal(client, playerLocation);
	}

	private Quetzal resolveArrivalTarget(MusicTrack musicTrack, TrackStep trackStep, Client client)
	{
		Quetzal dataDrivenTarget = resolveDataDrivenTarget(trackStep);
		if (dataDrivenTarget != null)
		{
			return dataDrivenTarget;
		}

		if (musicTrack != null && musicTrack.getTitle() != null)
		{
			if (musicTrack.getTitle().equalsIgnoreCase(TALKASTI_PEOPLE_TRACK))
			{
				return isQuetzalAvailable(client, Quetzal.KASTORI) ? Quetzal.KASTORI : Quetzal.TAL_TEKLAN;
			}
			if (musicTrack.getTitle().equalsIgnoreCase(UNDER_THE_MOUNTAIN_TRACK))
			{
				return isQuetzalAvailable(client, Quetzal.CAM_TORUM) ? Quetzal.CAM_TORUM : Quetzal.THE_TEOMAT;
			}
		}

		return null;
	}

	private Quetzal resolveDataDrivenTarget(TrackStep trackStep)
	{
		if (trackStep == null)
		{
			return null;
		}
		for (InteractionTarget interactionTarget : trackStep.getAllHighlights())
		{
			if (SpecialEntity.fromToken(interactionTarget.getEntity()) != SpecialEntity.QUETZAL)
			{
				continue;
			}
			if (interactionTarget.getData() == null)
			{
				continue;
			}
			String quetzalName = interactionTarget.getData().get(DATA_KEY_QUETZAL);
			if (quetzalName == null || quetzalName.isBlank())
			{
				continue;
			}
			for (Quetzal quetzal : Quetzal.values())
			{
				if (quetzal.name().equalsIgnoreCase(quetzalName.trim()))
				{
					return quetzal;
				}
			}
		}
		return null;
	}

	private Quetzal findNearestAvailableQuetzal(Client client, WorldPoint playerLocation)
	{
		Quetzal nearestQuetzal = null;
		int nearestDistance = Integer.MAX_VALUE;

		for (Quetzal quetzal : Quetzal.values())
		{
			if (!isQuetzalAvailable(client, quetzal))
			{
				continue;
			}

			int distance = playerLocation.distanceTo(quetzal.getLandingSiteLocation());
			if (distance < nearestDistance)
			{
				nearestDistance = distance;
				nearestQuetzal = quetzal;
			}
		}

		return nearestQuetzal;
	}

	private boolean isQuetzalAvailable(Client client, Quetzal quetzal)
	{
		return !quetzal.requiresBuild() || client.getVarbitValue(quetzal.getBuildGateVarbitId()) > 0;
	}

	private List<MusicTrackEntityPoint> buildRenuHighlight(WorldPoint landingSiteLocation, String hintText)
	{
		InteractionTarget renuInteraction = InteractionTarget.builder()
			.entity(RENU_ENTITY_NAME)
			.location(landingSiteLocation)
			.type(InteractionType.NPC)
			.hint(hintText)
			.action(TRAVEL_ACTION)
			.build();

		return List.of(MusicTrackEntityPoint.from(landingSiteLocation, renuInteraction));
	}
}

package org.dejaq.plugins.musictracker.track.special;

import java.awt.Color;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.ui.ColorScheme;
import org.dejaq.plugins.musictracker.MusicTrack;
import org.dejaq.plugins.musictracker.MusicTrackerPlugin;
import org.dejaq.plugins.musictracker.requirement.DynamicRequirement;
import org.dejaq.plugins.musictracker.requirement.ItemRequirement;
import org.dejaq.plugins.musictracker.requirement.collections.ItemCollections;
import org.dejaq.plugins.musictracker.track.InteractionTarget;
import org.dejaq.plugins.musictracker.track.InteractionType;
import org.dejaq.plugins.musictracker.track.MusicTrackEntityPoint;
import org.dejaq.plugins.musictracker.track.Route;
import org.dejaq.plugins.musictracker.track.TrackStep;

@Slf4j
public class RaceAgainstClockHandler implements SpecialTrackHandler
{
	private static final List<String> ROUTE_NAMES = List.of(
		"Route 1"
	);

	private static final int REQUIRED_BARRONITE_SHARD_QUANTITY = 750;

	private static final WorldPoint CAMDOZAAL_CENTER = new WorldPoint(2968, 5798, 0);
	private static final WorldPoint BARRONITE_ROCKS_MINING_LOCATION = new WorldPoint(2913, 5810, 0);
	private static final WorldPoint SACRED_FORGE_LOCATION = new WorldPoint(2956, 5810, 0);
	private static final WorldPoint VAULT_DOOR_LOCATION = new WorldPoint(2969, 5824, 0);

	private static final String BARRONITE_ROCKS_OBJECT_NAME = "Barronite Rocks";
	private static final String SACRED_FORGE_OBJECT_NAME = "Sacred Forge";
	private static final String VAULT_DOOR_OBJECT_NAME = "Vault Door";
	private static final String MINE_ACTION = "mine";
	private static final String FUEL_ACTION = "fuel";
	private static final String CHECK_ACTION = "check";
	private static final String OPEN_ACTION = "open";
	private static final String MINING_HINT_TEXT = "Mine 750 Barronite shards";
	private static final String PICKAXE_REQUIREMENT_TEXT = "Pickaxe to mine Barronite shards";
	private static final String CHECK_FORGE_HINT_TEXT = "Check Sacred Forge";
	private static final String VAULT_DOOR_HINT_TEXT = "Enter the Vault Door";
	private static final String RUINS_STEP_NAME = "Ruins";
	private static final int BARRONITE_ROCKS_SEARCH_RADIUS_IN_TILES = 12;
	private static final int CAMDOZAAL_RADIUS = 64;

	private static final Pattern SACRED_FORGE_LEFT_MESSAGE_PATTERN =
		Pattern.compile("You have (\\d+) Barronite shards? left", Pattern.CASE_INSENSITIVE);

	private static final Pattern SACRED_FORGE_CHECK_MESSAGE_PATTERN =
		Pattern.compile("You currently have (\\d+) Barronite shards? stored", Pattern.CASE_INSENSITIVE);

	private static final Pattern SACRED_FORGE_FUEL_MESSAGE_PATTERN =
		Pattern.compile("You stored (\\d+) Barronite shards? in the Sacred Forge", Pattern.CASE_INSENSITIVE);

	private int cachedTick = -1;
	private int cachedStageIndex = -1;
	private List<MusicTrackEntityPoint> cachedHighlights;

	private boolean hasCheckedSacredForge;
	private int storedBarroniteShardQuantity;


	@Override
	public List<String> getHandledRouteNames()
	{
		return ROUTE_NAMES;
	}

	@Override
	public List<DynamicRequirement<ItemRequirement>> getDynamicItems(
		MusicTrack musicTrack,
		Route route,
		MusicTrackerPlugin musicTrackerPlugin)
	{
		int currentBarroniteShardQuantity = musicTrackerPlugin.getPlayerState()
			.getItemQuantity(ItemID.CAMDOZAAL_BARRONITE_SHARD);
		int totalBarroniteShardQuantity = currentBarroniteShardQuantity + getKnownStoredBarroniteShardQuantity();

		boolean forgeHasRequiredShardQuantity = hasCheckedSacredForge
			&& storedBarroniteShardQuantity >= REQUIRED_BARRONITE_SHARD_QUANTITY;
		boolean readyToFuelToCompletion = !forgeHasRequiredShardQuantity
			&& totalBarroniteShardQuantity >= REQUIRED_BARRONITE_SHARD_QUANTITY;

		ItemRequirement barroniteShardRequirement = new ItemRequirement(
			ItemID.CAMDOZAAL_BARRONITE_SHARD,
			REQUIRED_BARRONITE_SHARD_QUANTITY
		);

		String shardDisplayText = Math.min(totalBarroniteShardQuantity, REQUIRED_BARRONITE_SHARD_QUANTITY)
			+ " / " + REQUIRED_BARRONITE_SHARD_QUANTITY + " Barronite Shards"
			+ (hasCheckedSacredForge ? "" : " (unverified)");

		Color shardColor = forgeHasRequiredShardQuantity
			? ColorScheme.PROGRESS_COMPLETE_COLOR
			: readyToFuelToCompletion
			? ColorScheme.PROGRESS_INPROGRESS_COLOR
			: ColorScheme.PROGRESS_ERROR_COLOR;

		boolean hasPickaxe = musicTrackerPlugin.getPlayerState()
			.hasItemFromCollection(ItemCollections.PICKAXES.getItems());

		ItemRequirement pickaxeRequirement = new ItemRequirement(
			ItemCollections.PICKAXES,
			1
		);
		pickaxeRequirement.setLabel(PICKAXE_REQUIREMENT_TEXT);

		Color pickaxeColor = hasPickaxe
			? ColorScheme.PROGRESS_COMPLETE_COLOR
			: ColorScheme.PROGRESS_ERROR_COLOR;

		return List.of(
			DynamicRequirement.of(barroniteShardRequirement, shardDisplayText, shardColor),
			DynamicRequirement.of(pickaxeRequirement, PICKAXE_REQUIREMENT_TEXT, pickaxeColor)
		);
	}

	@Override
	public DynamicRequirement<String> getDynamicNotes(MusicTrack musicTrack, Route route, MusicTrackerPlugin musicTrackerPlugin)
	{
		int currentBarroniteShardQuantity = musicTrackerPlugin.getPlayerState().getItemQuantity(ItemID.CAMDOZAAL_BARRONITE_SHARD);
		int totalBarroniteShardQuantity = currentBarroniteShardQuantity + getKnownStoredBarroniteShardQuantity();

		if (hasCheckedSacredForge && storedBarroniteShardQuantity >= REQUIRED_BARRONITE_SHARD_QUANTITY)
		{
			return DynamicRequirement.of(null, "The Sacred Forge has enough shards - head to the Vault Door.", ColorScheme.PROGRESS_COMPLETE_COLOR);
		}

		if (totalBarroniteShardQuantity >= REQUIRED_BARRONITE_SHARD_QUANTITY)
		{
			return DynamicRequirement.of(null,
				"You have " + totalBarroniteShardQuantity + " / " + REQUIRED_BARRONITE_SHARD_QUANTITY
					+ " Barronite shards total - fuel the Sacred Forge with what you're carrying to finish.",
				ColorScheme.PROGRESS_INPROGRESS_COLOR);
		}

		if (!hasCheckedSacredForge)
		{
			return DynamicRequirement.of(null,
				"Check the Sacred Forge to see how many shards you've already stored.",
				ColorScheme.PROGRESS_ERROR_COLOR);
		}

		int remainingShardsNeeded = REQUIRED_BARRONITE_SHARD_QUANTITY - totalBarroniteShardQuantity;
		String remainingShardsLabel = remainingShardsNeeded == 1 ? "shard" : "shards";
		return DynamicRequirement.of(null,
			"Mine " + remainingShardsNeeded + " more Barronite " + remainingShardsLabel
				+ " (" + totalBarroniteShardQuantity + " / " + REQUIRED_BARRONITE_SHARD_QUANTITY + " total).",
			ColorScheme.PROGRESS_ERROR_COLOR);
	}

	@Override
	public boolean hasVolatileDynamicHighlights(MusicTrack musicTrack, Route route, MusicTrackerPlugin musicTrackerPlugin)
	{
		return true;
	}

	@Override
	public List<MusicTrackEntityPoint> getDynamicEntityHighlights(MusicTrack musicTrack, Route route, TrackStep trackStep, int stageIndex, MusicTrackerPlugin musicTrackerPlugin)
	{
		Client client = musicTrackerPlugin.getClient();
		if (!client.isClientThread())
		{
			log.warn("getDynamicEntityHighlights called off the client thread; ignoring");
			return null;
		}

		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null)
		{
			return null;
		}

		boolean playerIsInsideCamdozaal = localPlayer.getWorldLocation().distanceTo(CAMDOZAAL_CENTER) <= CAMDOZAAL_RADIUS;

		if (trackStep != null && RUINS_STEP_NAME.equalsIgnoreCase(trackStep.getName()) && !playerIsInsideCamdozaal)
		{
			musicTrackerPlugin.getTrackNavigator().getNavigationCoordinator().forgetLastRequestedTarget();
			hasCheckedSacredForge = false;
			storedBarroniteShardQuantity = 0;
			invalidateHighlightCache();
			return null;
		}

		int currentTick = client.getTickCount();
		if (currentTick == cachedTick && stageIndex == cachedStageIndex && cachedHighlights != null)
		{
			return cachedHighlights;
		}

		int currentBarroniteShardQuantity = musicTrackerPlugin.getPlayerState().getItemQuantity(ItemID.CAMDOZAAL_BARRONITE_SHARD);
		int totalBarroniteShardQuantity = currentBarroniteShardQuantity + getKnownStoredBarroniteShardQuantity();

		List<MusicTrackEntityPoint> computedHighlights;
		WorldPoint targetWorldPoint;

		if (hasCheckedSacredForge && storedBarroniteShardQuantity >= REQUIRED_BARRONITE_SHARD_QUANTITY)
		{
			computedHighlights = buildVaultDoorHighlights();
			targetWorldPoint = VAULT_DOOR_LOCATION;
		}
		else if (totalBarroniteShardQuantity >= REQUIRED_BARRONITE_SHARD_QUANTITY)
		{
			computedHighlights = buildSacredForgeHighlights(false, currentBarroniteShardQuantity);
			targetWorldPoint = SACRED_FORGE_LOCATION;
		}
		else if (!hasCheckedSacredForge)
		{
			computedHighlights = buildSacredForgeHighlights(true, currentBarroniteShardQuantity);
			targetWorldPoint = SACRED_FORGE_LOCATION;
		}
		else
		{
			computedHighlights = buildMiningHighlights();
			targetWorldPoint = BARRONITE_ROCKS_MINING_LOCATION;
		}

		musicTrackerPlugin.getTrackNavigator().getNavigationCoordinator().requestShortestPathTo(targetWorldPoint);

		cachedTick = currentTick;
		cachedStageIndex = stageIndex;
		cachedHighlights = computedHighlights;
		return computedHighlights;
	}

	@Override
	public void onChatMessage(MusicTrack musicTrack, Route route, ChatMessage chatMessageEvent, MusicTrackerPlugin musicTrackerPlugin)
	{
		String message = chatMessageEvent.getMessage();
		if (message == null)
		{
			return;
		}

		Matcher checkMessageMatcher = SACRED_FORGE_CHECK_MESSAGE_PATTERN.matcher(message);
		if (checkMessageMatcher.find())
		{
			storedBarroniteShardQuantity = parseShardQuantity(checkMessageMatcher.group(1));
			hasCheckedSacredForge = true;
			invalidateHighlightCache();
			return;
		}

		Matcher emptyMessageMatcher = SACRED_FORGE_LEFT_MESSAGE_PATTERN.matcher(message);
		if (emptyMessageMatcher.find())
		{
			storedBarroniteShardQuantity = parseShardQuantity(emptyMessageMatcher.group(1));
			hasCheckedSacredForge = true;
			invalidateHighlightCache();
			return;
		}

		Matcher fuelMessageMatcher = SACRED_FORGE_FUEL_MESSAGE_PATTERN.matcher(message);
		if (fuelMessageMatcher.find())
		{
			int fueledShardQuantity = parseShardQuantity(fuelMessageMatcher.group(1));
			if (hasCheckedSacredForge)
			{
				storedBarroniteShardQuantity += fueledShardQuantity;
			}
			invalidateHighlightCache();
		}
	}

	private int parseShardQuantity(String rawShardQuantity)
	{
		try
		{
			return Integer.parseInt(rawShardQuantity);
		}
		catch (NumberFormatException shardQuantityParseException)
		{
			return 0;
		}
	}

	private int getKnownStoredBarroniteShardQuantity()
	{
		return hasCheckedSacredForge ? storedBarroniteShardQuantity : 0;
	}

	private void invalidateHighlightCache()
	{
		cachedTick = -1;
		cachedStageIndex = -1;
		cachedHighlights = null;
	}

	@Override
	public void reset()
	{
		invalidateHighlightCache();
		hasCheckedSacredForge = false;
		storedBarroniteShardQuantity = 0;
	}

	private List<MusicTrackEntityPoint> buildMiningHighlights()
	{
		List<MusicTrackEntityPoint> miningHighlights = new ArrayList<>();

		InteractionTarget barroniteRocksInteraction = InteractionTarget.builder()
			.entityId(-1)
			.entity(BARRONITE_ROCKS_OBJECT_NAME)
			.location(BARRONITE_ROCKS_MINING_LOCATION)
			.type(InteractionType.GAME_OBJECT)
			.action(MINE_ACTION)
			.searchRadius(BARRONITE_ROCKS_SEARCH_RADIUS_IN_TILES)
			.build();
		miningHighlights.add(MusicTrackEntityPoint.from(BARRONITE_ROCKS_MINING_LOCATION, barroniteRocksInteraction));

		InteractionTarget miningTileInteraction = InteractionTarget.builder()
			.entityId(-1)
			.location(BARRONITE_ROCKS_MINING_LOCATION)
			.type(InteractionType.TILE)
			.hint(MINING_HINT_TEXT)
			.build();
		miningHighlights.add(MusicTrackEntityPoint.from(BARRONITE_ROCKS_MINING_LOCATION, miningTileInteraction));

		return miningHighlights;
	}

	private List<MusicTrackEntityPoint> buildSacredForgeHighlights(boolean promptCheck, int currentBarroniteShardQuantity)
	{
		String hintText;
		String action;

		if (promptCheck)
		{
			hintText = CHECK_FORGE_HINT_TEXT;
			action = CHECK_ACTION;
		}
		else
		{
			String shardLabel = currentBarroniteShardQuantity == 1 ? "shard" : "shards";
			hintText = "Fuel Sacred Forge with " + currentBarroniteShardQuantity + " " + shardLabel;
			action = FUEL_ACTION;
		}

		InteractionTarget sacredForgeInteraction = InteractionTarget.builder()
			.entityId(-1)
			.entity(SACRED_FORGE_OBJECT_NAME)
			.location(SACRED_FORGE_LOCATION)
			.type(InteractionType.GAME_OBJECT)
			.hint(hintText)
			.action(action)
			.build();
		return List.of(MusicTrackEntityPoint.from(SACRED_FORGE_LOCATION, sacredForgeInteraction));
	}

	private List<MusicTrackEntityPoint> buildVaultDoorHighlights()
	{
		InteractionTarget vaultDoorInteraction = InteractionTarget.builder()
			.entityId(-1)
			.entity(VAULT_DOOR_OBJECT_NAME)
			.location(VAULT_DOOR_LOCATION)
			.type(InteractionType.GAME_OBJECT)
			.hint(VAULT_DOOR_HINT_TEXT)
			.action(OPEN_ACTION)
			.build();
		return List.of(MusicTrackEntityPoint.from(VAULT_DOOR_LOCATION, vaultDoorInteraction));
	}
}

package org.dejaq.plugins.musictracker.track.special;

import java.awt.Color;
import java.util.List;
import java.util.Locale;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.ui.ColorScheme;
import org.dejaq.plugins.musictracker.MusicTrack;
import org.dejaq.plugins.musictracker.MusicTrackerPlugin;
import org.dejaq.plugins.musictracker.requirement.DynamicRequirement;
import org.dejaq.plugins.musictracker.requirement.ItemRequirement;
import org.dejaq.plugins.musictracker.requirement.collections.ItemCollections;
import org.dejaq.plugins.musictracker.track.InteractionTarget;
import org.dejaq.plugins.musictracker.track.InteractionType;
import org.dejaq.plugins.musictracker.track.MusicTrackEntityPoint;
import org.dejaq.plugins.musictracker.track.Route;
import org.dejaq.plugins.musictracker.track.TrackStep;

@Slf4j
public class RighteousnessHandler implements SpecialTrackHandler
{
	private static final List<String> ENTRANA_ROUTE_NAMES = List.of("Entrana");

	private static final String MONK_OF_ENTRANA_NAME = "Monk of Entrana";
	private static final String BANK_DEPOSIT_BOX_NAME = "Bank deposit box";
	private static final String MYSTERIOUS_RUINS_NAME = "Mysterious ruins";

	private static final String MONK_TAKE_BOAT_HINT = "Take-boat";
	private static final String MONK_TAKE_BOAT_ACTION = "Take-boat";
	private static final String DEPOSIT_BOX_HINT = "Deposit all combat gear";
	private static final String DEPOSIT_BOX_ACTION = "Deposit";

	private static final String RUINS_HINT_ENTER = "Enter";
	private static final String RUINS_HINT_WEAR_THEN_ENTER = "Wear tiara then enter";
	private static final String RUINS_HINT_USE_TALISMAN = "Use talisman on ruins";

	private static final String NO_COMBAT_GEAR_REQUIREMENT_DISPLAY_TEXT = "No combat gear";

	private static final WorldPoint MONK_OF_ENTRANA_LOCATION = new WorldPoint(3046, 3237, 0);
	private static final WorldPoint BANK_DEPOSIT_BOX_LOCATION = new WorldPoint(3045, 3234, 0);
	private static final WorldPoint LAW_ALTAR_RUINS_LOCATION = new WorldPoint(2857, 3380, 0);

	private static final WorldPoint ENTRANA_ISLAND_BORDER_CENTER = new WorldPoint(2840, 3359, 0);
	private static final int ENTRANA_ISLAND_BORDER_RADIUS = 39;
	private static final int MONK_OF_ENTRANA_TRAVEL_HIGHLIGHT_DISTANCE_THRESHOLD = 30;

	@Override
	public List<String> getHandledRouteNames()
	{
		return ENTRANA_ROUTE_NAMES;
	}

	@Override
	public boolean hasVolatileDynamicHighlights(MusicTrack currentMusicTrack, Route currentRoute, MusicTrackerPlugin musicTrackerPlugin)
	{
		return true;
	}

	@Override
	public List<DynamicRequirement<ItemRequirement>> getDynamicItems(MusicTrack currentMusicTrack, Route currentRoute, MusicTrackerPlugin musicTrackerPlugin)
	{
		Color combatGearRequirementColor = canAccessEntrana(musicTrackerPlugin)
			? ColorScheme.PROGRESS_COMPLETE_COLOR
			: ColorScheme.PROGRESS_ERROR_COLOR;

		return addDynamicItems(currentRoute, musicTrackerPlugin,
			DynamicRequirement.of(null, NO_COMBAT_GEAR_REQUIREMENT_DISPLAY_TEXT, combatGearRequirementColor));
	}

	@Override
	public List<MusicTrackEntityPoint> getDynamicEntityHighlights(MusicTrack currentMusicTrack, Route currentRoute, TrackStep currentTrackStep, int currentStageIndex, MusicTrackerPlugin musicTrackerPlugin)
	{
		if (currentTrackStep == null)
		{
			return null;
		}

		Client gameClient = musicTrackerPlugin.getClient();
		if (!gameClient.isClientThread())
		{
			log.warn("getDynamicEntityHighlights called off the client thread; ignoring");
			return null;
		}

		WorldPoint currentPlayerLocation = resolveCurrentPlayerWorldLocation(gameClient);

		if (currentPlayerLocation != null && isPlayerOnEntranaIsland(currentPlayerLocation))
		{
			return buildRuinsHighlight(musicTrackerPlugin);
		}

		if (currentPlayerLocation != null && isPlayerNearMonkOfEntrana(currentPlayerLocation))
		{
			return buildTravelHighlight(musicTrackerPlugin);
		}

		if (currentTrackStep.hasEntity(MONK_OF_ENTRANA_NAME) || currentTrackStep.hasEntity(BANK_DEPOSIT_BOX_NAME))
		{
			return buildTravelHighlight(musicTrackerPlugin);
		}

		if (currentTrackStep.hasEntity(MYSTERIOUS_RUINS_NAME))
		{
			return buildRuinsHighlight(musicTrackerPlugin);
		}

		return null;
	}

	private WorldPoint resolveCurrentPlayerWorldLocation(Client gameClient)
	{
		Player localPlayer = gameClient.getLocalPlayer();
		return localPlayer != null ? localPlayer.getWorldLocation() : null;
	}

	private boolean isPlayerOnEntranaIsland(WorldPoint currentPlayerLocation)
	{
		return currentPlayerLocation.distanceTo(ENTRANA_ISLAND_BORDER_CENTER) <= ENTRANA_ISLAND_BORDER_RADIUS;
	}

	private boolean isPlayerNearMonkOfEntrana(WorldPoint currentPlayerLocation)
	{
		return currentPlayerLocation.distanceTo(MONK_OF_ENTRANA_LOCATION) < MONK_OF_ENTRANA_TRAVEL_HIGHLIGHT_DISTANCE_THRESHOLD;
	}

	private List<MusicTrackEntityPoint> buildTravelHighlight(MusicTrackerPlugin musicTrackerPlugin)
	{
		if (canAccessEntrana(musicTrackerPlugin))
		{
			InteractionTarget monkInteraction = InteractionTarget.builder()
				.entity(MONK_OF_ENTRANA_NAME)
				.location(MONK_OF_ENTRANA_LOCATION)
				.type(InteractionType.NPC)
				.hint(MONK_TAKE_BOAT_HINT)
				.action(MONK_TAKE_BOAT_ACTION)
				.build();

			return List.of(MusicTrackEntityPoint.from(MONK_OF_ENTRANA_LOCATION, monkInteraction));
		}

		InteractionTarget depositBoxInteraction = InteractionTarget.builder()
			.entity(BANK_DEPOSIT_BOX_NAME)
			.location(BANK_DEPOSIT_BOX_LOCATION)
			.type(InteractionType.GAME_OBJECT)
			.hint(DEPOSIT_BOX_HINT)
			.action(DEPOSIT_BOX_ACTION)
			.build();

		return List.of(MusicTrackEntityPoint.from(BANK_DEPOSIT_BOX_LOCATION, depositBoxInteraction));
	}

	private List<MusicTrackEntityPoint> buildRuinsHighlight(MusicTrackerPlugin musicTrackerPlugin)
	{
		String ruinsHint = resolveRuinsHint(musicTrackerPlugin);
		if (ruinsHint == null)
		{
			return null;
		}

		InteractionTarget ruinsInteraction = InteractionTarget.builder()
			.entityId(-1)
			.entity(MYSTERIOUS_RUINS_NAME)
			.location(LAW_ALTAR_RUINS_LOCATION)
			.type(InteractionType.GAME_OBJECT)
			.hint(ruinsHint)
			.build();

		return List.of(MusicTrackEntityPoint.from(LAW_ALTAR_RUINS_LOCATION, ruinsInteraction));
	}

	private String resolveRuinsHint(MusicTrackerPlugin musicTrackerPlugin)
	{
		ItemRequirement lawTiaraRequirement = new ItemRequirement(ItemCollections.LAW_ALTAR_WEARABLE, 1);
		if (musicTrackerPlugin.playerHasItemEquipped(lawTiaraRequirement))
		{
			return RUINS_HINT_ENTER;
		}

		ItemRequirement lawTalismanRequirement = new ItemRequirement(ItemCollections.LAW_ALTAR, 1);
		if (musicTrackerPlugin.playerHasItem(lawTalismanRequirement))
		{
			return RUINS_HINT_USE_TALISMAN;
		}

		if (musicTrackerPlugin.playerHasItem(lawTiaraRequirement))
		{
			return RUINS_HINT_WEAR_THEN_ENTER;
		}
		return null;
	}

	private boolean canAccessEntrana(MusicTrackerPlugin musicTrackerPlugin)
	{
		Client gameClient = musicTrackerPlugin.getClient();
		ItemManager itemManager = musicTrackerPlugin.getItemManager();

		ItemContainer equippedItemContainer = gameClient.getItemContainer(InventoryID.WORN);
		if (equippedItemContainer != null)
		{
			for (Item equippedItem : equippedItemContainer.getItems())
			{
				if (equippedItem != null && equippedItem.getId() > 0 && isEntranaBlockingItem(equippedItem.getId(), itemManager))
				{
					return false;
				}
			}
		}

		ItemContainer inventoryItemContainer = gameClient.getItemContainer(InventoryID.INV);
		if (inventoryItemContainer != null)
		{
			for (Item inventoryItem : inventoryItemContainer.getItems())
			{
				if (inventoryItem != null && inventoryItem.getId() > 0 && isEntranaBlockingItem(inventoryItem.getId(), itemManager))
				{
					return false;
				}
			}
		}

		return true;
	}

	private boolean isEntranaBlockingItem(int itemId, ItemManager itemManager)
	{
		if (ItemCollections.ENTRANA_BLOCKED.getItems().contains(itemId))
		{
			return false;
		}

		if (ItemCollections.ENTRANA_ALLOWED_BONUS.getItems().contains(itemId))
		{
			return true;
		}

		if (isJewellery(itemId, itemManager))
		{
			return false;
		}

		if (isAmmunition(itemId, itemManager))
		{
			return isDart(itemId, itemManager);
		}

		return hasCombatBonus(itemId, itemManager);
	}

	private boolean isJewellery(int itemId, ItemManager itemManager)
	{
		ItemStats itemStats = itemManager.getItemStats(itemId);
		if (itemStats == null || !itemStats.isEquipable())
		{
			return false;
		}

		ItemEquipmentStats itemEquipmentStats = itemStats.getEquipment();
		if (itemEquipmentStats == null)
		{
			return false;
		}

		int equipmentSlot = itemEquipmentStats.getSlot();
		if (equipmentSlot == EquipmentInventorySlot.RING.getSlotIdx()
			|| equipmentSlot == EquipmentInventorySlot.AMULET.getSlotIdx())
		{
			return true;
		}

		if (equipmentSlot == EquipmentInventorySlot.GLOVES.getSlotIdx())
		{
			String itemName = itemManager.getItemComposition(itemId).getName();
			return itemName != null && itemName.toLowerCase(Locale.ROOT).contains("bracelet");
		}

		return false;
	}

	private boolean isAmmunition(int itemId, ItemManager itemManager)
	{
		ItemStats itemStats = itemManager.getItemStats(itemId);
		if (itemStats == null || !itemStats.isEquipable())
		{
			return false;
		}

		ItemEquipmentStats itemEquipmentStats = itemStats.getEquipment();
		return itemEquipmentStats != null && itemEquipmentStats.getSlot() == EquipmentInventorySlot.AMMO.getSlotIdx();
	}

	private boolean isDart(int itemId, ItemManager itemManager)
	{
		String itemName = itemManager.getItemComposition(itemId).getName();
		return itemName != null && itemName.toLowerCase(Locale.ROOT).contains("dart");
	}

	private boolean hasCombatBonus(int itemId, ItemManager itemManager)
	{
		ItemStats itemStats = itemManager.getItemStats(itemId);
		if (itemStats == null || !itemStats.isEquipable())
		{
			return false;
		}

		ItemEquipmentStats itemEquipmentStats = itemStats.getEquipment();
		if (itemEquipmentStats == null)
		{
			return false;
		}

		int[] combatBonuses = {
			itemEquipmentStats.getAstab(),
			itemEquipmentStats.getAslash(),
			itemEquipmentStats.getAcrush(),
			itemEquipmentStats.getAmagic(),
			itemEquipmentStats.getArange(),
			itemEquipmentStats.getDstab(),
			itemEquipmentStats.getDslash(),
			itemEquipmentStats.getDcrush(),
			itemEquipmentStats.getDmagic(),
			itemEquipmentStats.getDrange(),
			itemEquipmentStats.getStr(),
			itemEquipmentStats.getRstr()
		};

		for (int combatBonus : combatBonuses)
		{
			if (combatBonus != 0)
			{
				return true;
			}
		}

		if (itemEquipmentStats.getMdmg() != 0)
		{
			return true;
		}

		return false;
	}
}

package org.dejaq.plugins.musictracker.track.special;

public enum SpecialEntity
{
	QUETZAL,
	FAIRY_RING;

	public static SpecialEntity fromToken(String token)
	{
		if (token == null || token.isBlank())
		{
			return null;
		}
		for (SpecialEntity specialEntity : values())
		{
			if (specialEntity.name().equalsIgnoreCase(token.trim()))
			{
				return specialEntity;
			}
		}
		return null;
	}
}

package org.dejaq.plugins.musictracker.track.special;

import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import org.dejaq.plugins.musictracker.MusicTrack;
import org.dejaq.plugins.musictracker.MusicTrackerPlugin;
import org.dejaq.plugins.musictracker.requirement.DynamicRequirement;
import org.dejaq.plugins.musictracker.requirement.ItemRequirement;
import org.dejaq.plugins.musictracker.requirement.LevelRequirement;
import org.dejaq.plugins.musictracker.track.InteractionTarget;
import org.dejaq.plugins.musictracker.track.MusicTrackEntityPoint;
import org.dejaq.plugins.musictracker.track.Route;
import org.dejaq.plugins.musictracker.track.TrackStep;

public interface SpecialTrackHandler
{
	List<String> getHandledRouteNames();

	default List<SpecialEntity> getHandledEntities()
	{
		return List.of();
	}

	default List<TrackStep> contributeTrackSteps(MusicTrack musicTrack, Route route, List<TrackStep> existingTrackSteps)
	{
		return existingTrackSteps;
	}

	default DynamicRequirement<String> getDynamicQuest(MusicTrack musicTrack, Route route, MusicTrackerPlugin musicTrackerPlugin)
	{
		return null;
	}

	default List<DynamicRequirement<ItemRequirement>> getDynamicItems(MusicTrack musicTrack, Route route, MusicTrackerPlugin musicTrackerPlugin)
	{
		return List.of();
	}

	default List<DynamicRequirement<ItemRequirement>> getDynamicItemRecommendations(MusicTrack musicTrack, Route route, MusicTrackerPlugin musicTrackerPlugin)
	{
		return List.of();
	}

	default List<DynamicRequirement<LevelRequirement>> getDynamicLevels(MusicTrack musicTrack, Route route, MusicTrackerPlugin musicTrackerPlugin)
	{
		return List.of();
	}

	default List<DynamicRequirement<LevelRequirement>> getDynamicLevelRecommendations(MusicTrack musicTrack, Route route, MusicTrackerPlugin musicTrackerPlugin)
	{
		return List.of();
	}

	default DynamicRequirement<String> getDynamicNotes(MusicTrack musicTrack, Route route, MusicTrackerPlugin musicTrackerPlugin)
	{
		return null;
	}

	default boolean canProgress(MusicTrack musicTrack, Route route, MusicTrackerPlugin musicTrackerPlugin)
	{
		return true;
	}

	default Integer getForcedStageIndex(MusicTrack musicTrack, Route route, int currentStageIndex, WorldPoint currentPlayerLocation, MusicTrackerPlugin musicTrackerPlugin)
	{
		return null;
	}

	default List<MusicTrackEntityPoint> getDynamicEntityHighlights(MusicTrack musicTrack, Route route, TrackStep trackStep, int stageIndex, MusicTrackerPlugin musicTrackerPlugin)
	{
		return null;
	}

	default boolean hasVolatileDynamicHighlights(MusicTrack musicTrack, Route route, MusicTrackerPlugin musicTrackerPlugin)
	{
		return false;
	}

	default void onChatMessage(MusicTrack musicTrack, Route route, ChatMessage chatMessageEvent, MusicTrackerPlugin musicTrackerPlugin)
	{
	}

	default void reset()
	{
	}

	default List<DynamicRequirement<ItemRequirement>> addDynamicItems(
		Route route, MusicTrackerPlugin musicTrackerPlugin, List<DynamicRequirement<ItemRequirement>> additionalItems)
	{
		List<ItemRequirement> staticItems = route != null ? route.getItems() : null;
		return mergeStaticWithDynamicAdditions(staticItems, item -> item.getDisplayText(musicTrackerPlugin.getItemManager()), additionalItems);
	}

	default List<DynamicRequirement<ItemRequirement>> addDynamicItems(
		Route route, MusicTrackerPlugin musicTrackerPlugin, DynamicRequirement<ItemRequirement> additionalItem)
	{
		return addDynamicItems(route, musicTrackerPlugin, List.of(additionalItem));
	}

	default List<DynamicRequirement<ItemRequirement>> addDynamicItemRecommendations(
		Route route, MusicTrackerPlugin musicTrackerPlugin, List<DynamicRequirement<ItemRequirement>> additionalItemRecommendations)
	{
		List<ItemRequirement> staticItemRecommendations = route != null ? route.getRecommendedItems() : null;
		return mergeStaticWithDynamicAdditions(staticItemRecommendations, item -> item.getDisplayText(musicTrackerPlugin.getItemManager()), additionalItemRecommendations);
	}

	default List<DynamicRequirement<ItemRequirement>> addDynamicItemRecommendations(
		Route route, MusicTrackerPlugin musicTrackerPlugin, DynamicRequirement<ItemRequirement> additionalItemRecommendation)
	{
		return addDynamicItemRecommendations(route, musicTrackerPlugin, List.of(additionalItemRecommendation));
	}

	default List<DynamicRequirement<LevelRequirement>> addDynamicLevels(
		Route route, List<DynamicRequirement<LevelRequirement>> additionalLevels)
	{
		List<LevelRequirement> staticLevels = route != null ? route.getLevels() : null;
		return mergeStaticWithDynamicAdditions(staticLevels, SpecialTrackHandler::formatLevelRequirement, additionalLevels);
	}

	default List<DynamicRequirement<LevelRequirement>> addDynamicLevels(
		Route route, DynamicRequirement<LevelRequirement> additionalLevel)
	{
		return addDynamicLevels(route, List.of(additionalLevel));
	}

	default List<DynamicRequirement<LevelRequirement>> addDynamicLevelRecommendations(
		Route route, List<DynamicRequirement<LevelRequirement>> additionalLevelRecommendations)
	{
		List<LevelRequirement> staticLevelRecommendations = route != null ? route.getRecommendedLevels() : null;
		return mergeStaticWithDynamicAdditions(staticLevelRecommendations, SpecialTrackHandler::formatLevelRequirement, additionalLevelRecommendations);
	}

	default List<DynamicRequirement<LevelRequirement>> addDynamicLevelRecommendations(
		Route route, DynamicRequirement<LevelRequirement> additionalLevelRecommendation)
	{
		return addDynamicLevelRecommendations(route, List.of(additionalLevelRecommendation));
	}

	default List<MusicTrackEntityPoint> addDynamicEntityHighlights(TrackStep trackStep, List<MusicTrackEntityPoint> additionalHighlights)
	{
		List<MusicTrackEntityPoint> combinedHighlights = new ArrayList<>();
		if (trackStep != null && trackStep.getAllHighlights() != null)
		{
			for (InteractionTarget interactionTarget : trackStep.getAllHighlights())
			{
				MusicTrackEntityPoint staticHighlight = toEntityHighlight(trackStep, interactionTarget);
				if (staticHighlight != null)
				{
					combinedHighlights.add(staticHighlight);
				}
			}
		}
		if (additionalHighlights != null)
		{
			combinedHighlights.addAll(additionalHighlights);
		}
		return combinedHighlights;
	}

	default List<MusicTrackEntityPoint> addDynamicEntityHighlights(TrackStep trackStep, MusicTrackEntityPoint additionalHighlights)
	{
		return addDynamicEntityHighlights(trackStep, List.of(additionalHighlights));
	}

	private static MusicTrackEntityPoint toEntityHighlight(TrackStep trackStep, InteractionTarget interactionTarget)
	{
		if (interactionTarget == null)
		{
			return null;
		}
		WorldPoint highlightLocation = interactionTarget.getLocation() != null
			? interactionTarget.getLocation()
			: trackStep.getDestination();
		if (highlightLocation == null)
		{
			return null;
		}
		return MusicTrackEntityPoint.from(highlightLocation, interactionTarget);
	}

	private static <T> List<DynamicRequirement<T>> mergeStaticWithDynamicAdditions(
		List<T> staticRequirements, Function<T, String> displayTextResolver, List<DynamicRequirement<T>> additions)
	{
		List<DynamicRequirement<T>> combined = new ArrayList<>();
		if (staticRequirements != null)
		{
			for (T staticRequirement : staticRequirements)
			{
				combined.add(DynamicRequirement.of(staticRequirement, displayTextResolver.apply(staticRequirement), null));
			}
		}
		if (additions != null)
		{
			combined.addAll(additions);
		}
		return combined;
	}

	private static String formatLevelRequirement(LevelRequirement levelRequirement)
	{
		return levelRequirement.getLevel() + " " + levelRequirement.getSkill().getName();
	}
}

package org.dejaq.plugins.musictracker.track.special;

import java.util.List;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import org.dejaq.plugins.musictracker.MusicTrack;
import org.dejaq.plugins.musictracker.MusicTrackerPlugin;
import org.dejaq.plugins.musictracker.requirement.ItemRequirement;
import org.dejaq.plugins.musictracker.requirement.collections.ItemCollections;
import org.dejaq.plugins.musictracker.track.InteractionTarget;
import org.dejaq.plugins.musictracker.track.InteractionType;
import org.dejaq.plugins.musictracker.track.MusicTrackEntityPoint;
import org.dejaq.plugins.musictracker.track.Route;
import org.dejaq.plugins.musictracker.track.TrackStep;

@Slf4j
public class StratosphereHandler implements SpecialTrackHandler
{
	private static final List<String> ZANARIS_ROUTE_NAMES = List.of("Zanaris");

	private static final WorldPoint ZANARIS_CENTER = new WorldPoint(2432, 4422, 0);
	private static final int ZANARIS_RADIUS = 64;
	private static final int WALL_JUNCTION_X = 2430;
	private static final int WALL_JUNCTION_Y = 4400;

	private static final int JUTTING_WALL_66_REQUIRED_AGILITY_LEVEL = 66;
	private static final int JUTTING_WALL_46_REQUIRED_AGILITY_LEVEL = 46;

	private static final WorldPoint JUTTING_WALL_66_LOCATION = new WorldPoint(2409, 4401, 0);
	private static final WorldPoint JUTTING_WALL_46_LOCATION = new WorldPoint(2400, 4403, 0);
	private static final WorldPoint MYSTERIOUS_RUINS_LOCATION = new WorldPoint(2407, 4376, 0);

	private static final String JUTTING_WALL_ENTITY_NAME = "Jutting wall";
	private static final String MYSTERIOUS_RUINS_ENTITY_NAME = "Mysterious ruins";

	private static final String HINT_ENTER = "Enter";
	private static final String HINT_WEAR_THEN_ENTER = "Wear tiara then enter";
	private static final String HINT_USE_TALISMAN = "Use talisman on ruins";

	@Getter
	@RequiredArgsConstructor
	private enum StratospherePhase
	{
		JUTTING_WALL_66(JUTTING_WALL_66_LOCATION, JUTTING_WALL_ENTITY_NAME, "66 Agility"),
		JUTTING_WALL_46(JUTTING_WALL_46_LOCATION, JUTTING_WALL_ENTITY_NAME, "46 Agility"),
		MYSTERIOUS_RUINS(MYSTERIOUS_RUINS_LOCATION, MYSTERIOUS_RUINS_ENTITY_NAME, "Enter / Use talisman on");

		private final WorldPoint location;
		private final String entityName;
		private final String hintText;
	}

	private int cachedTick = -1;
	private int cachedStageIndex = -1;
	private List<MusicTrackEntityPoint> cachedHighlights;

	@Override
	public List<String> getHandledRouteNames()
	{
		return ZANARIS_ROUTE_NAMES;
	}

	@Override
	public boolean hasVolatileDynamicHighlights(MusicTrack musicTrack, Route route, MusicTrackerPlugin musicTrackerPlugin)
	{
		return true;
	}

	@Override
	public List<MusicTrackEntityPoint> getDynamicEntityHighlights(MusicTrack musicTrack, Route route, TrackStep trackStep, int stageIndex, MusicTrackerPlugin musicTrackerPlugin)
	{
		Client client = musicTrackerPlugin.getClient();
		if (!client.isClientThread())
		{
			log.warn("getDynamicEntityHighlights called off the client thread; ignoring");
			return null;
		}

		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null)
		{
			return null;
		}

		WorldPoint playerLocation = localPlayer.getWorldLocation();
		if (playerLocation.distanceTo(ZANARIS_CENTER) > ZANARIS_RADIUS)
		{
			return null;
		}

		int currentTick = client.getTickCount();
		if (currentTick == cachedTick && stageIndex == cachedStageIndex && cachedHighlights != null)
		{
			return cachedHighlights;
		}

		int currentAgilityLevel = getCurrentAgilityLevel(musicTrackerPlugin);
		StratospherePhase currentPhase = resolveCurrentPhase(playerLocation, currentAgilityLevel);

		List<MusicTrackEntityPoint> computedHighlights = buildHighlightForPhase(currentPhase, musicTrackerPlugin);

		musicTrackerPlugin.getTrackNavigator().getNavigationCoordinator().requestShortestPathTo(currentPhase.getLocation());

		cachedTick = currentTick;
		cachedStageIndex = stageIndex;
		cachedHighlights = computedHighlights;
		return computedHighlights;
	}

	@Override
	public void reset()
	{
		cachedTick = -1;
		cachedStageIndex = -1;
		cachedHighlights = null;
	}

	private StratospherePhase resolveCurrentPhase(WorldPoint playerLocation, int currentAgilityLevel)
	{
		if (hasOvershotIntoRuinsZone(playerLocation))
		{
			return StratospherePhase.MYSTERIOUS_RUINS;
		}

		if (currentAgilityLevel >= JUTTING_WALL_66_REQUIRED_AGILITY_LEVEL)
		{
			return StratospherePhase.JUTTING_WALL_66;
		}
		if (currentAgilityLevel >= JUTTING_WALL_46_REQUIRED_AGILITY_LEVEL)
		{
			return StratospherePhase.JUTTING_WALL_46;
		}
		return StratospherePhase.MYSTERIOUS_RUINS;
	}

	private boolean hasOvershotIntoRuinsZone(WorldPoint playerLocation)
	{
		return playerLocation.getX() < WALL_JUNCTION_X && playerLocation.getY() < WALL_JUNCTION_Y;
	}

	private int getCurrentAgilityLevel(MusicTrackerPlugin musicTrackerPlugin)
	{
		return musicTrackerPlugin.getClient().getRealSkillLevel(Skill.AGILITY);
	}

	private List<MusicTrackEntityPoint> buildHighlightForPhase(StratospherePhase phase, MusicTrackerPlugin musicTrackerPlugin)
	{
		InteractionTarget target = InteractionTarget.builder()
			.entityId(-1)
			.entity(phase.getEntityName())
			.location(phase.getLocation())
			.type(InteractionType.GAME_OBJECT)
			.hint(resolveHintText(phase, musicTrackerPlugin))
			.build();

		return List.of(MusicTrackEntityPoint.from(phase.getLocation(), target));
	}

	private String resolveHintText(StratospherePhase phase, MusicTrackerPlugin musicTrackerPlugin)
	{
		if (phase != StratospherePhase.MYSTERIOUS_RUINS)
		{
			return phase.getHintText();
		}

		ItemRequirement wearableRequirement = new ItemRequirement(ItemCollections.COSMIC_ALTAR_WEARABLE, 1);
		if (musicTrackerPlugin.playerHasItemEquipped(wearableRequirement))
		{
			return HINT_ENTER;
		}

		if (musicTrackerPlugin.playerHasItem(wearableRequirement))
		{
			return HINT_WEAR_THEN_ENTER;
		}

		ItemRequirement talismanRequirement = new ItemRequirement(ItemCollections.COSMIC_ALTAR, 1);
		if (musicTrackerPlugin.playerHasItem(talismanRequirement))
		{
			return HINT_USE_TALISMAN;
		}

		return phase.getHintText();
	}
}

